  "{n} more — expand": "还有 {n} 条 — 展开",
  "Dismiss every open row of this band (↺ reopens)": "把这一段所有未处理的项标为已看（↺ 可重开）",
  "Show the notices": "展开通知",
  "Acknowledge every finished job here that you have not looked at yet — the red count drops, nothing is deleted": "把这里所有已结束、你还没看过的任务标为已看——红色计数会降下来，不会删除任何东西",
  "Could not mark them seen": "无法标为已看",
  "Unknown event": "未知事件",
  "Unknown events / new fields on known records (harness records VibeSpace does not recognize)": "未知事件 / 已知记录上的新字段（VibeSpace 不认识的 harness 记录）",
  "{n} unknown events / new fields": "{n} 个未知事件 / 新字段",
  "sample": "样本",
  "Live view — phases, labels and states come from the run’s own progress records (the same ones the chat card shows); token totals are final when the run finishes.": "实时视图——阶段、标签和状态来自这次运行自己的进度记录（与聊天卡片显示的是同一份）；token 总量在运行结束后才是最终值。",
  "No transcript on disk yet": "磁盘上还没有它的对话记录",
  "Keep Claude Code conversations for (days)": "Claude Code 对话保留天数",
  "Claude Code deletes conversation transcripts older than this at every start (its own default is 30 days). VibeSpace writes the value into ~/.claude/settings.json (cleanupPeriodDays) at start-up and whenever it changes, and onto remote hosts when their agent tools are installed. 0 = leave Claude Code's own setting alone.": "Claude Code 每次启动都会删除超过这个天数的对话记录（它自己的默认值是 30 天）。VibeSpace 在启动时和每次修改时把这个值写进 ~/.claude/settings.json（cleanupPeriodDays），安装远程主机的 agent 工具时也一并写入。0 = 不动 Claude Code 自己的设置。",
  "Notices": "通知",
  "notice": "通知",
  "{n} for your information": "{n} 条仅供知晓",
  "{n} notices (for your information)": "{n} 条通知（仅供知晓）",
  "{n} tool uses": "{n} 次工具调用",
  "A question in this conversation was answered.": "这个对话里的一个提问已被回答。",
  "A question in this conversation was dismissed.": "这个对话里的一个提问已被驳回。",
  "Open terminal in this session": "在这个会话里打开终端",
  "OpenCode will restore the files to the snapshot taken before this message and stage every later message for removal. Sending a new prompt makes it permanent; \"Restore rolled-back messages\" undoes it.": "OpenCode 会把文件恢复到这条消息之前的快照，并把之后的所有消息标记为待删除。再发一条新提示就会永久生效；“恢复被回滚的消息”可以撤销。",
  "Restore rolled-back messages": "恢复被回滚的消息",
