  "Show the saved workspace presets button in the toolbar": "在工具栏显示工作区预设按钮",
  "Show the file explorer button in the toolbar": "在工具栏显示文件管理器按钮",
  "Which screen edge the session sidebar docks to": "会话侧栏停靠在屏幕哪一侧",
  "Dock the taskbar (window list, desktop previews, usage) to the top or bottom of the screen": "任务栏（窗口列表、桌面预览、用量）停靠在屏幕顶部或底部",
  "Auto-hide slides the taskbar away and reveals it when the pointer touches the screen edge. Hidden removes it entirely (desktops still switch with Ctrl+Alt+Left/Right)": "自动隐藏会将任务栏滑出屏幕，指针触碰屏幕边缘时显示。隐藏则完全移除（仍可用 Ctrl+Alt+左/右 切换桌面）",
  "Show the virtual-desktop miniature previews in the taskbar": "在任务栏显示虚拟桌面缩略预览",
  "Show the 5h/7d rate-limit donuts in the taskbar": "在任务栏显示 5 小时 / 7 天用量环形图",
  "Show the \"N windows\" counter/list button in the taskbar": "在任务栏显示\"N 个窗口\"计数/列表按钮",
  "Enable Ctrl+\\ command mode for keyboard-driven window management": "启用 Ctrl+\\ 命令模式，用键盘管理窗口",
  "Snap windows to grid cells or screen edges when dragging": "拖动时将窗口吸附到网格单元或屏幕边缘",
  "Hold Shift while dragging title bar to select a range of grid cells": "拖动标题栏时按住 Shift 可框选一片网格区域",
  "How much of the taskbar height the desktop preview occupies (rest goes to label text)": "桌面预览占任务栏高度的比例（其余留给文字标签）",
  "Which bar hosts each movable element, in what order ({zone: [elementId, …]}). Managed by Customize mode (⚙ → Customize UI… → drag elements); edit by hand only if you know what you are doing.": "每个可移动元素位于哪条栏、顺序如何（{zone: [elementId, …]}）。由自定义模式管理（⚙ → Customize UI… → 拖动元素）；除非清楚后果，请勿手动编辑。",
  "Alignment per area: taskbar-items left/center (Windows-11-style centered icons), toolbar-center left/center/right, taskbar-tray left/right end. Managed by Customize mode.": "各区域对齐方式：任务栏图标 左/居中（Windows 11 风格居中图标）、工具栏中区 左/中/右、任务栏托盘 左/右端。由自定义模式管理。",
  "Per-spring config: {mode:\"flex\", weight:1-9} (strength = flex-grow share) or {mode:\"fixed\", px:N} (rigid spacer). Managed by Customize mode (click a spring).": "每个弹性间隔的配置：{mode:\"flex\", weight:1-9}（权重 = flex-grow 份额）或 {mode:\"fixed\", px:N}（固定间隔）。由自定义模式管理（点击间隔）。",
  "Allow tab bar to wrap into multiple rows when there are many tabs (like a flow layout)": "标签很多时允许标签栏换行为多行（流式布局）",
  "How prominently the focused window is highlighted (subtle = shadow only, normal = accent border, strong = border + glow)": "聚焦窗口的高亮强度（轻微 = 仅阴影，普通 = 强调色边框，强烈 = 边框 + 光晕）",
  "Auto-adjust text colors to meet this contrast ratio (4.5 = WCAG AA). Set to 1 to disable.": "自动调整文字颜色以满足此对比度（4.5 = WCAG AA）。设为 1 禁用。",
  "Keep viewport scroll position anchored when terminal is resized": "终端大小调整时保持视口滚动位置",
  "When to show the orange blink on idle terminals": "终端空闲时何时显示橙色闪烁提醒",
  "Dense document-style layout instead of chat bubbles. Closer to TUI information density.": "文档式紧凑布局（而非聊天气泡），信息密度更接近 TUI。",
  "How to visually distinguish user vs assistant messages in compact mode.": "紧凑模式下如何区分用户与助手消息。",
  "Default mode for new sessions and single-click resume from sidebar": "新会话及侧栏单击恢复的默认模式",
  "Select an alias or choose \"Custom...\" to type a specific model ID (e.g. claude-opus-4-6-20250414). Applies to NEW sessions: a resumed conversation keeps the model the Claude CLI recorded for it (a transcript names the model that served a turn but never its 1M-context variant, so VibeSpace commands none) — set one for a specific conversation under Session parameters on its card.": "选择别名，或选\"自定义…\"输入具体模型 ID（如 claude-opus-4-6-20250414）。适用于新建会话：恢复的对话保留 Claude CLI 自己记录的模型（转录只说哪个模型服务了某一轮，从不说它的 1M 上下文变体，所以 VibeSpace 不指定）— 要为某个对话单独指定，用卡片上的「会话参数」。",
  "Default Claude permission mode for new or resumed Claude sessions.": "新建或恢复 Claude 会话的默认权限模式。",
  "Select a level or choose \"Custom...\" to type any value (e.g. xhigh). Applies to NEW sessions: nothing Claude writes records the effort a turn ran at, so a resume commands none and the CLI’s own config decides — set one for a specific conversation under Session parameters on its card.": "选择级别，或选\"自定义…\"输入任意值（如 xhigh）。适用于新建会话：Claude 写下的任何东西都没有记录某一轮跑在什么强度上，所以恢复时不指定，由 CLI 自己的配置决定 — 要为某个对话单独指定，用卡片上的「会话参数」。",
  "Extra Claude CLI args appended when starting a Claude session.": "启动 Claude 会话时追加的 CLI 参数。",
  "Renderer for terminal-mode Claude sessions. \"Fullscreen\" forces the flicker-free alternate-screen renderer with virtualized scrollback (CLAUDE_CODE_NO_FLICKER=1, same as /tui fullscreen); \"Classic\" forces the main-screen renderer; \"Auto\" follows the preference saved by the CLI (/tui). Applies to newly started sessions.": "终端模式 Claude 会话的渲染器。\"全屏\"强制使用无闪烁备用屏渲染器（CLAUDE_CODE_NO_FLICKER=1，等同 /tui fullscreen）；\"经典\"强制主屏渲染器；\"自动\"跟随 CLI 保存的偏好（/tui）。对新启动的会话生效。",
  "Select a known model or choose \"Custom...\" to type a specific model ID. Applies to NEW sessions: a resumed conversation keeps its own value (set one for a specific conversation under Session parameters on its card).": "选择已知模型，或选\"自定义…\"输入具体模型 ID。适用于新建会话：恢复的对话保留它自己的取值（要为某个对话单独指定，用卡片上的「会话参数」）。",
  "Default Codex permission mode for new or resumed Codex sessions.": "新建或恢复 Codex 会话的默认权限模式。",
  "Default Codex reasoning effort for NEW Codex sessions. A resumed conversation keeps the effort its own last turn ran at; set one for a specific conversation under Session parameters on its card.": "新建 Codex 会话的默认推理强度。恢复的对话保留它自己上一轮跑的强度；要为某个对话单独指定，用卡片上的「会话参数」。",
  "Extra Codex CLI args appended when starting a Codex session.": "启动 Codex 会话时追加的 CLI 参数。",
