  "New subscription — log in on {host}…": "新订阅——在 {host} 上登录…",
  "· master held by VibeSpace": "· 主副本存于 VibeSpace",
  "VibeSpace holds the MASTER copy of this key; sessions get derived working copies on their machines (swept on removal). ⋯ → “Show key…” reveals the value.": "VibeSpace 持有这把 key 的主副本；会话运行时向所在机器下发派生的工作副本（移除时一并清理）。⋯ → “查看 key…” 可查看完整值。",
  "Show key…": "查看 key…",
  "API key — {name}": "API key——{name}",
  "The full key value (the MASTER copy held by VibeSpace). Save it in a password manager — the Anthropic Console cannot re-show it.": "完整的 key 值（VibeSpace 持有的主副本）。请存入密码管理器——Anthropic Console 网页无法重新查看它。",
  "Could not read the key": "无法读取 key",
  "Remove \"{name}\"? The roster is one shared list — this deletes the MASTER key copy held by VibeSpace (it disappears from every machine’s view) and sweeps the per-session working copies it placed on hosts. The Anthropic Console cannot re-show an existing key’s value, so make sure it’s saved elsewhere first. Running sessions keep working.": "移除“{name}”？账号列表是全局共享的一份——这会删除 VibeSpace 保存的密钥主副本（所有机器视图都会消失），并清理它按会话下发到各机器上的工作副本。Anthropic Console 网页无法重新查看已有 key 的完整值，请先确认已在别处保存。运行中的会话不受影响。",
  "· from {host}": "· 来自 {host}",
  "Imported from {host}’s Console login — an independent copy held in VibeSpace (not linked to {host}); usable on any machine.": "从 {host} 的 Console 登录导入——是保存在 VibeSpace 里的独立副本（与 {host} 无实时关联），可在任何机器上使用。",
  "Account note": "账号备注",
  "Shown as a small tag on the account row (e.g. “from laptop backup”). Empty clears it.": "以小标签显示在账号行上（例如“从 the devbox 备份恢复”）。留空则清除。",
  "Set note…": "设置备注…",
  "Edit note…": "编辑备注…",
  "Add subscription — log in on {host}": "添加订阅——在 {host} 上登录",
  "A terminal opened ON {host} — sign in there. The login lives on {host} only; sessions on it can then pick this account.": "已在 {host} 上打开终端——请在那里完成登录。该登录只保存在 {host} 上；之后 {host} 上的会话即可选择这个账号。",
  "Inject Task Group context": "注入任务组上下文",
  "Deliver each session's Task Group context (objective, shared-context folder index, activity log, update diffs) into the agent via hooks. OFF: agents get no group payloads at all — the reporting tools below still work if enabled. The per-group \"Inject context\" checkbox in the group's detail window is the finer-grained version of this.": "通过 hook 把会话所属任务组的上下文（目标、共享上下文文件夹索引、活动日志、更新 diff）注入给 agent。关闭：agent 完全收不到任务组内容——下面的汇报工具若开启仍可用。任务组详情窗口里的\"注入上下文\"勾选框是更细粒度的版本。",
  "Agent tool: vibespace-status (board state)": "Agent 工具：vibespace-status（状态板）",
  "Lets agents self-report working/blocked/needs-input/… onto the session board. OFF: the tool is no longer taught in injected context or reminders, its endpoint refuses with skip-and-continue guidance, and the stop-time bookkeeping nudge (which is keyed on status staleness) never fires. Synthesized states (idle detection) keep working.": "让 agent 在会话板上自报 working/blocked/needs-input 等状态。关闭：注入上下文与提醒不再教这个工具，端点会拒绝并提示\"跳过并继续\"，且以状态过期为判据的 stop 簿记提醒不再触发。合成状态（空闲检测）不受影响。",
  "Agent tool: vibespace-ask (the For you tray)": "Agent 工具：vibespace-ask（「待你处理」）",
  "Lets agents mirror questions/decisions into the For you tray. OFF: not taught, endpoint refuses with skip-and-continue guidance — agents ask only in chat.": "让 agent 把提问/待决策同步到「待你处理」。关闭：不再教学，端点拒绝并提示跳过——agent 只在聊天里提问。",
  "Agent tool: vibespace-task (activity log & backlog)": "Agent 工具：vibespace-task（活动日志与 backlog）",
  "Lets agents log finished work into the group activity log and park items in the group backlog. OFF: not taught, the progress/backlog write endpoints refuse with skip-and-continue guidance; reading group state (vibespace-task show) still works while context injection is on.": "让 agent 把完成的工作记入任务组活动日志、把事项停放进组 backlog。关闭：不再教学，progress/backlog 写端点拒绝并提示跳过；上下文注入开启时读取组状态（vibespace-task show）仍可用。",
  "Minimize": "最小化",
  "Restore": "还原",
  "Move to Desktop": "移动到桌面",
  "(no windows)": "（无窗口）",
  "(minimized)": "（已最小化）",
  "Close group": "关闭组",
  "Close {n} tabs?": "关闭 {n} 个标签页？",
  "Close {n} tabs": "关闭 {n} 个标签页",
  "{n} windows grouped": "{n} 个窗口已分组",
  "Windows in this group": "此组中的窗口",
  "Overlapping this window": "与当前窗口重叠",
  "Current desktop windows": "当前桌面窗口",
  "All windows": "所有窗口",
  "Title-bar \"Switch window\" scope": "标题栏\"切换窗口\"范围",
  "Which windows the title-bar right-click menu's \"Switch window\" submenu lists: only windows overlapping this one (classic), every window on the current desktop, or all windows across desktops (entries name their desktop; picking one switches to it).": "标题栏右键菜单的\"切换窗口\"子菜单列出哪些窗口：仅与当前窗口重叠的（经典行为）、当前桌面的所有窗口、或跨桌面的全部窗口（条目标注所在桌面，选中即切换过去）。",
  "Read": "读取",
  "{n} thinking": "{n} 段思考",
  "{n} Bash": "{n} 条 Bash",
  "{n} writes": "{n} 次写入",
  "Collapse runs of working cards": "折叠连续的工作卡片",
  "Consecutive working cards (kinds picked below) fold behind a one-line summary, like the Claude Code TUI — click to expand. The summary shows per-kind counts, the touched file names (✎ marks writes, memory/… marks agent-memory files) and a ✗ failure count. Searching expands everything.": "连续的工作卡片（类型见下方选择）折叠为一行摘要，类似 Claude Code TUI——点击展开。摘要包含各类型计数、涉及的文件名（✎ 标记写入，memory/… 标记 agent 记忆文件）和 ✗ 失败计数。搜索时全部展开。",
  "Card kinds that collapse": "参与折叠的卡片类型",
  "Thinking blocks": "思考块",
  "File reads": "文件读取",
  "File writes (Write/Edit/Patch)": "文件写入（Write/Edit/Patch）",
  "Create task": "创建任务",
  "Update task": "更新任务",
