  "{pct}% used": "已用 {pct}%",
  "{rows}×{cols} grid": "{rows}×{cols} 网格",
  "{state} — {activity} (observed by VibeSpace; the agent can set its own state with vibespace-status). Click to set manually.": "{state} — {activity}（由 VibeSpace 观察；agent 可用 vibespace-status 设置自己的状态）。点击手动设置。",
  "~/.claude/.credentials.json — no re-login on the new instance": "~/.claude/.credentials.json——新实例上无需重新登录",
  "Re-login on this machine…": "在本机重新登录…",
  "Log in on this machine…": "在本机登录…",
  "A terminal opened — sign in as “{name}”. Only this account’s login is refreshed; every other login is untouched.": "已打开一个终端——请以“{name}”身份登录。只会刷新这个账号的登录，其它登录一律不受影响。",
  "✓ “{name}” signed in again": "✓ “{name}” 已重新登录",
  "The login belongs to a DIFFERENT account ({email}) — saved as the new entry “{new}”. “{name}” stays signed out.": "这次登录属于另一个账号（{email}）——已另存为新条目“{new}”。“{name}”保持登出状态。",
  "The login belongs to “{other}” ({email}) — its login was refreshed there instead. “{name}” stays signed out.": "这次登录属于“{other}”（{email}）——已把该账号的登录刷新到它自己的条目上。“{name}”保持登出状态。",
  "Switched back to Local — the previously selected remote host no longer exists.": "已切回本机——之前选择的远程主机已不存在。",
  "The machine’s global CLI login is this same subscription — its quota is shown merged here.": "本机全局 CLI 登录与该账号同属一个订阅——配额已合并显示。",
