  "Each session can pick its account (New Session dialog / card ⚙). Subscriptions bill your Pro/Max plan; API keys bill pay-per-use. The starred account is the default when a session doesn’t pick one.": "每个会话都可选择账号（新建会话对话框 / 卡片 ⚙）。订阅走你的 Pro/Max 套餐；API key 按量付费。加星的账号是会话未指定时的默认账号。",
