  "A terminal opened — sign in with the ChatGPT account you want to add. Your other logins are untouched; VibeSpace captures it automatically.": "已打开一个终端——用你想添加的 ChatGPT 账号登录。你其它的登录不受影响；VibeSpace 会自动捕获。",
  "Add ChatGPT account": "添加 ChatGPT 账号",
  "Add ChatGPT account…": "添加 ChatGPT 账号…",
  "CLI login on {host}": "{host} 上的 CLI 登录",
  "ChatGPT / OpenAI accounts": "ChatGPT / OpenAI 账号",
  "ChatGPT login": "ChatGPT 登录",
  "ChatGPT login (on the host)": "ChatGPT 登录（在远程主机上）",
  "Connect cloud folders and shared datasets": "连接云端文件夹与共享数据集",
  "Copy the Console key found on {host} (…{tail}) into VibeSpace so any machine can use it": "将在 {host} 上发现的 Console 密钥（…{tail}）复制到 VibeSpace，任何机器都能使用",
  "Each Codex session can pick its ChatGPT login (New Session dialog / card ⚙). Held in isolated logins, switchable per session; threads stay shared.": "每个 Codex 会话都可选择自己的 ChatGPT 登录（新建会话对话框 / 卡片 ⚙）。以隔离登录保存，可按会话切换；线程仍然共享。",
