  "Log in on {host}…": "在 {host} 上登录…",
  "Logs in ON the selected remote host (its own login, not VibeSpace)": "在所选远程主机上登录（是它自己的登录，不属于 VibeSpace）",
  "Name this account (e.g. Work ChatGPT, Personal)": "为此账号命名（例如：工作 ChatGPT、个人）",
  "Opens a terminal ON {host} — this login lands on that machine, not in VibeSpace": "在 {host} 上打开一个终端——此登录落在那台机器上，不在 VibeSpace 中",
  "Remove \"{name}\" from VibeSpace? Sessions already running keep working.": "从 VibeSpace 中移除“{name}”？已在运行的会话不受影响。",
  "Sign in another ChatGPT account — stored in VibeSpace (not on any one machine), switchable per session": "登录另一个 ChatGPT 账号——保存在 VibeSpace 中（不落在任何一台机器上），可按会话切换",
