  "This machine’s CLI login and “{name}” are the same {vendor} account — one quota, usage shown merged — but two separate sign-ins: each expires and is renewed on its own, and signing in one does not sign in the other.": "本机的 CLI 登录与“{name}”是同一个 {vendor} 账号——同一份额度，用量合并显示——但它们是两份独立的登录：各自到期、各自续期，登录其中一个不会让另一个登录。",
