  "Prompt cache hit rate (last turn): {pct}% of input tokens were read from cache ({read} of {total}). Higher = cheaper + faster.": "提示词缓存命中率（上一轮）：{pct}% 的输入 tokens 读取自缓存（{total} 中的 {read}）。越高越省钱、越快。",
