  "ChatGPT": "ChatGPT",
  "ChatGPT (Codex)": "ChatGPT (Codex)",
  "Checking the connection…": "正在检查连接…",
  "Claude": "Claude",
  "Click ⟳ to re-scan this host.": "点击 ⟳ 重新扫描此主机。",
  "Codex": "Codex",
  "Complete this account’s login in Manage agents first.": "请先在 Manage agents 中完成该账号的登录。",
  "Connecting to {host}…": "正在连接 {host}…",
  "Connection lost before the goal was set — your command was restored to the input": "目标设置前连接已断开——你的指令已还原到输入框",
  "Could not change the default account — {reason}": "无法更改默认账号 — {reason}",
  "Could not check the integration on {host} — {reason}": "无法检查 {host} 上的集成状态 — {reason}",
  "Could not load plugins — the server did not answer.": "无法加载插件——服务器未响应。",
  "Could not load usage: {msg}": "无法加载用量：{msg}",
  "Could not read the hook status — {reason}": "无法读取 hook 状态 — {reason}",
