  "not logged in on this machine": "未在本机登录",
  "opus (latest, 200k)": "opus（最新，200k 上下文）",
  "opus[1m] (latest, 1M)": "opus[1m]（最新，1M 上下文）",
  "port or ip:port (e.g. 5173, or 10.0.0.5:8080 for a LAN machine)": "端口或 ip:port（如 5173，或局域网机器用 10.0.0.5:8080）",
