  "Each entry is the layout as it was BEFORE a change. Restoring reloads the page; your sessions are not touched.": "每一条都是某次变更之前的布局。恢复会刷新页面；会话不受影响。",
  "Restore this layout? Your current one becomes a rollback point too, so this is undoable.": "恢复这个布局？当前布局也会成为一个回滚点，所以此操作可撤销。",
