  "Delivery log": "投递日志",
  "Auto-notify": "自动通知",
  "Background jobs owned by this conversation message it when they finish, fail, get parked, or ask for input; while it is closed, notifications queue and inject at resume. Toggle globally in Settings → Integration, per group in the group window.": "本对话名下的后台任务在完成/失败/被停放/请求输入时会给它发消息；对话关闭期间通知排队，resume 时注入。全局开关在 设置 → 集成，按组开关在组窗口。",
  "Background jobs: notify the owner conversation": "后台任务：通知所属对话",
  "Inherit (global)": "继承（全局）",
  "External visibility": "对外可见性",
  "Closed (default)": "封闭（默认）",
  "Visible": "可见",
  "Messageable": "可见且可发消息",
  "Agent-to-agent messaging reach for sessions OUTSIDE this group. Closed (default): outsiders cannot list or message this group's sessions. Visible: outsiders can list them. Messageable: outsiders can also send them messages. Inside the group, sessions always see and message each other.": "组外 agent 会话对本组的消息可达性。封闭（默认）：组外既看不到也发不了消息。可见：组外可以列出本组会话。可见且可发消息：组外还能给它们发消息。组内会话之间始终互相可见可发。",
  "Job auto-notify": "任务自动通知",
  "Local session discovery via device daemon": "本地会话发现走设备守护进程",
  "Local sessions via device daemon (R6)": "本地会话走设备守护进程（R6）",
  "New local chat sessions run as device-daemon pipe sessions instead of dtach — the session-brain final form (survives server restarts via the daemon). Existing sessions are never migrated; any daemon failure falls back to dtach at spawn. Leave off until the device-assisted consumer path has soaked.": "新建的本地聊天会话改为设备守护进程 pipe 会话而非 dtach——session-brain 终态（借守护进程在服务器重启后存活）。现有会话绝不迁移；守护进程任何故障在 spawn 时回落 dtach。设备辅助消费路径充分浸泡前请保持关闭。",
  "Off": "关",
  "On": "开",
  "Stopped {n} other process(es) that were still writing this conversation on {host} — resuming cleanly.": "已停止 {host} 上仍在写入此对话的 {n} 个其他进程——干净地恢复。",
  "The 5s session-list sweep reads its filesystem facts (lock files, transcript listing, tail ids) from the device daemon's snapshot — computed in a daemon child process, so a slow or network-mounted home directory can never stall the server. Local enrichment (window mapping, tmux) is unaffected. Falls back to the local scan on any failure.": "5 秒会话列表巡检的文件系统事实（锁文件、转录清单、尾部 id）改读设备守护进程的快照——在守护进程子进程里计算，慢速/网络挂载的家目录再也拖不住服务器。本地增强（窗口映射、tmux）不受影响。任何失败回落本地扫描。",
  "The passive statusline feed only carries the 5h/7d windows — model-scoped weekly limits (e.g. Fable) can ONLY come from asking Anthropic’s usage endpoint with the account’s own login token. This is the same non-billable call the CLI makes when you run /usage, throttled to ≥60s per account and honoring rate-limit backoff, and it NEVER runs on a timer. It is user-initiated traffic, categorically different from the background polling that has gotten accounts banned — but it is still an off-CLI request with a subscription token, so it is your call: Manual = only when you click ⟳; Auto = also once when you open the quota popup and the data is stale; Off = never (the ⟳ button disappears and scoped limits stay unknown); Auto via the CLI = a background loop spawns `claude -p /usage` (the official binary makes the fetch — this app never calls the endpoint itself) with a BURN-AWARE cadence: refreshes within minutes when the dead-reckoner sees real spending drift, 45min-with-jitter staleness cap for active accounts, and idle accounts are never polled.": "被动 statusline 只带 5h/7d 窗口——按模型的周限额（如 Fable）只能用账号自己的登录 token 询问 Anthropic 的 usage 端点。这与你运行 /usage 时 CLI 发出的同一非计费调用，按账号 ≥60 秒节流并遵守限流退避，且绝不定时运行。它是用户发起的流量，与导致封号的后台轮询有本质区别——但仍是携订阅 token 的 CLI 外请求，由你决定：手动 = 仅点击 ⟳ 时；自动 = 打开配额弹窗且数据过期时也刷新一次；关 = 从不（⟳ 按钮消失，按模型限额保持未知）；CLI 自动 = 后台循环 spawn `claude -p /usage`（官方二进制发起请求——本应用从不自己调端点），节奏燃烧感知：dead-reckoner 看到真实消耗漂移时几分钟内刷新，活跃账号 45 分钟带抖动的过期上限，闲置账号从不轮询。",
  "This conversation is NOT notified when its background jobs finish — agents must poll. Toggle globally in Settings → Integration, per group in the group window.": "本对话的后台任务结束时不会收到通知——agent 只能自己 poll。全局开关在 设置 → 集成，按组开关在组窗口。",
  "When a background job finishes, fails, is parked, or needs input, its owner conversation gets a message through Claude Code’s own cross-session messaging inbox (delivered by the CLI under its inbound rules; an idle session starts a turn, billed like a typed prompt). When the conversation is closed, the notification is stashed and injected the next time it resumes. Per-group override in the Task Group detail window; per-job override at creation (--notify on/off).": "后台任务完成/失败/被停放/需要输入时，其所属对话会通过 Claude Code 自己的跨会话消息收件箱收到一条消息（由 CLI 按其入站规则投递；空闲会话会开启一个 turn，计费等同你手打的一条消息）。对话关闭期间通知暂存，下次 resume 时注入。按组覆盖在任务组详情窗口；按任务覆盖在创建时（--notify on/off）。",
  "When a background job owned by one of this group's conversations finishes, fails, or asks for input, message that conversation (Claude Code cross-session messaging; stashed for resume when it is closed). \"Inherit\" follows the global Integration setting.": "本组对话名下的后台任务完成/失败/请求输入时给该对话发消息（Claude Code 跨会话消息；对话关闭则暂存到 resume）。“继承”跟随全局集成设置。",
