  "A model id the agent offers (provider/model, e.g. opencode/big-pickle) — the list fills from the agent once a session has started; empty keeps the agent default. Applies to NEW sessions: a resumed conversation keeps the model OpenCode’s own session record names (that needs the OpenCode background service; without it the default applies and the server log says which rung it used).": "agent 提供的模型 id（provider/model，如 opencode/big-pickle）——列表在第一个会话启动后由 agent 填充；留空则使用 agent 默认值。适用于新建会话：恢复的对话保留 OpenCode 自己会话记录里的模型（需要 OpenCode 后台服务；没有它时则应用默认值，服务器日志会说明用的是哪一档）。",
  "Default OpenCode session mode for new sessions: build executes tools per its permission rules, plan disallows edits.": "新 OpenCode 会话的默认模式：build 按其权限规则执行工具，plan 禁止编辑。",
  "Extra OpenCode CLI args appended when starting an OpenCode session.": "启动 OpenCode 会话时追加的额外 CLI 参数。",
