  "Upload .vsp package": "上传 .vsp 包",
  "The package is validated before it is placed under data/plugins/<id>/. Plugins that ask for capabilities beyond the sandbox are enabled only after you review them.": "包会先校验再放入 data/plugins/<id>/。申请沙箱之外能力的插件要经你审阅后才能启用。",
