  "No plugins installed. Use Install plugin… (a folder, a git URL, a .vsp file or a GitHub release) — docs/examples/hello-plugin is the smallest complete one.": "尚未安装插件。用「安装插件…」（文件夹、git 地址、.vsp 文件或 GitHub release）— docs/examples/hello-plugin 是最小的完整示例。",
