  "Sending during a turn": "本轮进行中发送",
  "Queue it until the turn ends": "排队到本轮结束",
  "Enter sends now": "Enter 立即送入",
  "{key} sends now": "{key} 立即送入",
  "Alt+Enter queues until the turn ends": "Alt+Enter 排队到回合结束",
  "Handed to the turn": "已交给本轮",
  "Stays with the stopped turn": "留在已停止的回合中",
  "Handed to the running turn — the agent reads it at its next tool call": "已交给正在进行的回合 · 下一次工具调用时送达",
  "Stop came before the agent read it — it stays in the conversation, and the agent reads it with your next message": "停止先于 agent 读到它——它留在对话里，agent 会在你的下一条消息时一并读到",
  "{k} message(s) you sent into the turn stay with it": "{k} 条已送入本轮的消息留在本轮中",
  "Enter hands it to the running turn — the agent reads it at its next tool call": "Enter 立即送入正在进行的回合——agent 在下一次工具调用时读到",
  "Alt+Enter queues it until the turn ends — editable until then": "Alt+Enter 排队到回合结束——在那之前都可以编辑",
  "Enter queues it — it runs after this turn": "Enter 排队 —— 本轮结束后运行",
  "Alt+Enter injects it into the running turn (the agent sees it at its next reply)": "Alt+Enter 注入正在进行的这一轮（agent 在下一次回复时就会看到）",
  "Sent — but it could not be injected into the running turn; it will run when the turn ends.": "已发送 —— 但没能注入正在进行的这一轮；它会在本轮结束后运行。",
  'agent default': 'agent 默认',
  'Response style': '回复风格',
  'Response style: {v} — set at spawn; a change applies on the next resume': '回复风格：{v}——启动时设定，改动在下次 resume 生效',
  'Response style: the agent default — click to pick (applies on the next resume)': '回复风格：agent 默认——点击选择（下次 resume 生效）',
  'Response style: {v} — click to change it right now (applies from the next turn)': '回复风格：{v}——点击可立即更改（从下一轮起生效）',
  'Response style: whatever this agent’s own config says — click to pick one (applies from the next turn)': '回复风格：由该 agent 自己的配置决定——点击可选一个（从下一轮起生效）',
  'Response style “{v}” is saved and applies on the next resume (now running: {cur})': '回复风格「{v}」已保存，下次 resume 生效（当前运行：{cur}）',
  'Response style “{v}” applies on the next resume': '回复风格「{v}」将在下次 resume 生效',
  'Response style cleared — applies on the next resume': '已清除回复风格——下次 resume 生效',
  'Response style “{v}” applies from the next turn': '回复风格「{v}」将从下一轮起生效',
  'Response style cleared — the agent’s own config applies again': '已清除回复风格——回到该 agent 自己的配置',
  'This agent applies a style change to the running session, from its next turn.': '该 agent 可以对运行中的会话改风格，从下一轮起生效。',
  '(saved: {v} — applies on the next resume)': '（已保存：{v}——下次 resume 生效）',
  'your choice for this session': '本会话的手动选择',
  'Task-Group default': '岗位默认',
  'instance default': '实例默认',
  'harness default — the agent’s own config decides': 'agent 默认——由它自己的配置决定',
  'lead with results, skip preamble': '先给结果，省掉铺垫',
  'explain choices and patterns': '解释取舍与代码模式',
  'teach while doing': '边做边教',
  'act first, minimize interruptions': '先动手，尽量不打断你',
  'warmer, more conversational': '更热络、更像聊天',
  'terse and task-focused': '简短，只谈任务',
  'Default response style (Codex)': '默认回复风格（Codex）',
  'The personality new Codex chat sessions start with. Blank = leave it to your own ~/.codex/config.toml (this is the default; VibeSpace used to force "pragmatic" on every session). Unlike Claude, a running Codex session CAN be re-styled from the chat status bar — it applies from the next turn.': '新建 Codex 聊天会话使用的 personality。留空 = 交给你自己的 ~/.codex/config.toml（这是默认；VibeSpace 曾对每个会话强制写死 "pragmatic"）。与 Claude 不同，运行中的 Codex 会话可以在聊天状态栏里改风格——从下一轮起生效。',
  'Generated image': '生成的图片',
  'Prompt': '提示词',
  'Sleeping': '休眠中',
  'remaining': '剩余',
  'Slept': '已休眠',
  'Response style “{v}” is saved for this conversation — the agent is still on {cur}; pick it again to apply it now': '回复风格「{v}」已为本对话保存——agent 当前仍是 {cur}；再点一次即可立刻应用',
  'This session’s agent started before live style switching — restart it to apply a change.': '本会话的 agent 在“实时改风格”上线前就启动了——重启会话才能应用改动。',
  'what this session started with': '本会话启动时的值',
  'saved — applies on the next resume': '已保存——下次 resume 生效',
  // OpenCode background service plugin (2026-09-07): first-use offer, ⚙ → Plugins card, sidebar hint row
  "Enable & start": "启用并启动",
  "Enable…": "启用…",
  "Forced OFF by the environment (VIBESPACE_OPENCODE_SERVE=0) — the switch below is ignored on this instance.": "已被环境变量强制关闭 (VIBESPACE_OPENCODE_SERVE=0) —— 本实例忽略下面的开关。",
  "Forced ON by the environment (VIBESPACE_OPENCODE_SERVE=1) — the switch below is ignored on this instance.": "已被环境变量强制开启 (VIBESPACE_OPENCODE_SERVE=1) —— 本实例忽略下面的开关。",
  "Lists, opens, resumes and forks stopped {name} conversations in the sidebar": "在侧边栏列出、打开、恢复并 fork 已停止的 {name} 对话",
  "Not now": "暂不",
  "Running sessions do not need it. You will only be asked once — ⚙ → Plugins can turn it on later.": "运行中的会话不需要它。只会询问这一次 —— 之后可在 ⚙ → 插件 中开启。",
  "Runs `opencode serve` on 127.0.0.1 (loopback only) using your own installed CLI — nothing is downloaded and nothing is exposed": "用你自己安装的 CLI 在 127.0.0.1(仅本地回环)运行 `opencode serve` —— 不下载任何东西, 也不对外暴露",
  "Start again": "重新启动",
  "Starting the {name} background service…": "正在启动 {name} 后台服务…",
  "Stopped {name} conversations are hidden — its background service is off.": "已停止的 {name} 对话被隐藏 —— 它的后台服务未开启。",
  "Stops as soon as you disable it in ⚙ → Plugins, and VibeSpace stops it by itself if it starts burning CPU or memory": "在 ⚙ → 插件 中关闭即刻停止; 若它开始吃 CPU 或内存, VibeSpace 会自行停掉它",
  "The background service for {name} is off — turn it on in ⚙ → Plugins.": "{name} 的后台服务未开启 —— 请在 ⚙ → 插件 中开启。",
  "The {name} background service has not answered yet — check ⚙ → Plugins.": "{name} 后台服务尚未响应 —— 请查看 ⚙ → 插件。",
  "Turn on the {name} background service?": "开启 {name} 后台服务?",
  "turned off": "已关闭",
  "running on 127.0.0.1:{port}": "运行中, 127.0.0.1:{port}",
  "started by VibeSpace": "由 VibeSpace 启动",
  "stopped as a runaway": "因失控被停止",
  "blocked by a serve we could not identify": "被一个无法确认身份的 serve 挡住",
