  "This is your own browser window (an app); the Agent browser is separate": "这是你自己的浏览器窗口（一个应用）；Agent 浏览器是另一回事",
  "Open URL (optional)": "打开网址（可选）",
  "Keep the profile after it closes": "关闭后保留配置目录",
