  "push off": "推送关闭",
  "push is not exclusive here — fell back to cursor kicks, polling returned to the fast cadence ({missed} of {total} records, {pct}%, were first seen by the reconciliation poll)": "推送在这里不是独占的 —— 已回落到只推进游标, 轮询恢复快节奏({total} 条记录里有 {missed} 条, {pct}%, 先被对账轮询看到)",
  "push unavailable: {why}": "推送不可用: {why}",
  "push not started": "推送未启动",
  "push live — cursor kicks only (declared shared)": "推送在线 —— 只推进游标(已声明共用)",
  "push live — cursor kicks only (exclusivity not declared)": "推送在线 —— 只推进游标(未声明独占度)",
  "push silent for {age} — polling at the fast cadence until it speaks": "推送已沉默 {age} — 在它出声之前按快节奏轮询",
  "push silent — polling at the fast cadence until it speaks": "推送沉默 — 在它出声之前按快节奏轮询",
  "push {state} — polling at the fast cadence": "推送 {state} — 按快节奏轮询",
  "Re-declare exclusive and retry": "重新声明独占并重试",
  "Push…": "推送…",
  "Push lane — {label}": "推送通道 — {label}",
  "The claim was withdrawn by measurement. Re-declaring it clears the counters and retries the lane once.": "这个声明已被度量撤回。重新声明会清零计数器并重试通道一次。",
  "Exclusivity declaration": "独占度声明",
  "unknown — declare nothing: push only kicks the cursor (default)": "unknown —— 不做声明: 推送只推进游标(默认)",
  "shared — other clients use this app: push only kicks the cursor": "shared —— 别的客户端也在用这个应用: 推送只推进游标",
  "exclusive — this instance is the only client: push carries messages, the poll reconciles every 15 min": "exclusive — 这个实例是唯一客户端: 推送携带消息, 轮询每 15 分钟对账",
  "The platform does not say how many clients share the app, so exclusivity is asserted here and MEASURED by the product: records the reconciliation poll sees before push do not happen on an exclusive lane. Past 2% over 20 records the lane demotes itself to cursor kicks and says so.": "平台不告诉我们有几个客户端共用这个应用, 所以独占度在这里由你断言、由产品度量: 真正独占的通道上不会有先被对账轮询看到的记录。20 条样本以上超过 2% 时通道会自己降级成只推进游标, 并说出来。",
  "Add rule": "添加规则",
  "Agent · {name}": "Agent · {name}",
  "Assign & filter…": "分配与过滤…",
  "Authority": "权限",
  "Coalesce pushed messages before waking an agent (seconds)": "唤醒 agent 之前合并推送来的消息(秒)",
  "Deliver": "投递",
  "Direct send is not offered here: {why}": "这里不提供直接发送: {why}",
  "Estimate failed": "估计失败",
  "Estimating…": "估计中…",
  "Filter is incomplete: {why}": "过滤器不完整: {why}",
  "Last wake was held or stashed: {why}": "上一次唤醒被扣住或暂存了: {why}",
  "Last wake: {n} message(s) delivered via {lane} — {why}": "上一次唤醒: {n} 条消息经 {lane} 投递 — {why}",
  "Match": "匹配",
  "No rules yet — add one below. With no rule nothing matches (a wake is money, so the filter fails closed).": "还没有规则 —— 在下面加一条。没有规则时什么都不匹配(唤醒要花钱, 所以过滤器默认关闭)。",
  "No wake latency can be claimed: this scan lane has no source right now ({why})": "无法声明唤醒延迟: 这条扫描通道此刻没有来源({why})",
  "Pick an agent or a group to wake.": "选一个要唤醒的 agent 或组。",
  "Polling batches a minute of messages into ONE wake by nature; a push lane delivers them one by one, so a burst of 30 would become 30 billed turns. While a push lane carries messages, matched hits are gathered for this many seconds and delivered as one wake that lists them all. 0 = wake per message. Poll and scan lanes are already batches and never wait.": "轮询天然把一分钟的消息合并成一次唤醒; 推送通道是一条一条送来的, 于是 30 条的爆发会变成 30 个计费 turn。当推送通道携带消息时, 命中的消息会攒这么多秒, 再作为一次列出全部的唤醒投递。0 = 每条消息唤醒一次。轮询与扫描通道本来就是批次, 从不等待。",
  "Request failed": "请求失败",
  "The stored authority is \"send\" but it reads as draft: {why}": "存下来的权限是“发送”, 但读取时被夹成草稿: {why}",
  "Wake": "唤醒",
  "Wake latency unknown": "唤醒延迟未知",
  "Wakes arrive within ~{age} — push carries messages here, one wake per message (coalescing is off)": "唤醒在约 {age} 内到达 —— 这里由推送携带消息, 每条消息一次唤醒(合并已关闭)",
  "Wakes arrive within ~{age} — push carries messages here; hits are coalesced for {n} s so a burst is one wake": "唤醒在约 {age} 内到达 —— 这里由推送携带消息; 命中会合并 {n} 秒, 一次爆发只算一次唤醒",
  "Wakes arrive within ~{age} — push only kicks the cursor here; the poll carries the messages": "唤醒在约 {age} 内到达 —— 这里推送只踢游标; 消息由轮询携带",
  "Wakes arrive within ~{age} — the poll is on its reconciliation cadence while push is declared exclusive": "唤醒在约 {age} 内到达 —— 推送声明独占时轮询处于对账节奏",
  "Wakes arrive within ~{age} — this conversation is polled": "唤醒在约 {age} 内到达 —— 这个会话由轮询获取",
  "Wakes arrive within ~{age} — this conversation is read by a scan of the local client ({source})": "唤醒在约 {age} 内到达 —— 这个会话由本地客户端的扫描读取({source})",
  "all messages": "全部消息",
  "any rule": "任一规则",
  "arrives between (HH:MM–HH:MM)": "到达时间在(HH:MM–HH:MM)",
  "contains keyword": "包含关键词",
  "digest every {m} min": "每 {m} 分钟一份摘要",
  "does not contain": "不包含",
