  "estimated ~{a}/day when set; actually {b}/day since (7-day measurement)": "设置时估计约 {a}/天; 从那以后实际 {b}/天(7 天度量)",
  "every message": "每一条消息",
  "every rule": "每条规则",
  "filtered": "已过滤",
  "from (name or address)": "来自(名字或地址)",
  "has an attachment": "带附件",
  "ids or names, comma-separated": "id 或名字, 逗号分隔",
  "may send": "可发送",
  "mentions": "提到",
  "name or id": "名字或 id",
  "one digest per window": "每个窗口一份摘要",
  "only the newest {n} records were read; older ones exist unread": "只读了最新的 {n} 条记录; 更早的还没读",
  "only {d} days of history are stored — the rate is over that span": "只存了 {d} 天历史 —— 速率按这一段算",
  "sender is one of": "发送者是其中之一",
  "subject contains": "主题包含",
  "text": "文本",
  "wake": "唤醒",
  "{kind} · {name} (not live now)": "{kind} · {name}(此刻不在线)",
  "{n} matched message(s) are waiting for the next window or turn": "{n} 条匹配的消息在等下一个窗口或 turn",
  "~{n}/day would wake (of ~{m}/day)": "约 {n}/天会唤醒(共约 {m}/天)",
  "(a guard setting could not be read: {why} — review, fail closed)": "(有一项护栏设置读不出来: {why} —— 按审批处理, 保守拒绝)",
  "(the stored policy value was not understood — review, fail closed)": "(存下来的策略值无法理解 —— 按审批处理, 保守拒绝)",
  "A proposal carrying an attachment goes to review even on a \"send directly\" channel. Off = an agent with send authority on a \"send directly\" channel sends files without asking. Also switched in the policy row (a conversation's or an account's Reach & policy…).": "带附件的提案即使在“直接发送”的频道上也要经过审批。关 = 在“直接发送”的频道上，有发送权限的智能体不问你就发出文件。也可在策略行里切换（会话或账号的“可见性与策略…”）。",
  "A proposal whose text carries a link goes to review even on a channel whose policy is \"send directly\". A guard can only tighten a policy, never relax it. Also switched in the policy row (a conversation's or an account's Reach & policy…).": "正文带链接的提案即使在策略为“直接发送”的频道上也要经过审批。护栏只能让策略更严, 绝不放宽。也可在策略行里切换（会话或账号的“可见性与策略…”）。",
  "Access requests": "访问请求",
  "An IANA zone such as Asia/Shanghai or America/Los_Angeles. Outside working hours every proposal goes to review. Leave empty and nothing is guessed: a wrong zone would silently send everything (or nothing) to review.": "IANA 时区, 如 Asia/Shanghai 或 America/Los_Angeles。非工作时间内每条提案都要审批。留空则不做任何猜测: 错误的时区会静默地把所有东西(或什么都不)送去审批。",
  "Approve": "批准",
  "Approve…": "批准…",
  "Open the proposal to approve it": "打开提案后批准",
  "Approve (this session, this conversation)": "批准(仅这个会话, 仅这个对话)",
  "Approve edited": "批准修改后的版本",
  "Approved": "已批准",
  "Edit…": "编辑…",
