  "Grant": "授予",
  "Grant reach to…": "把可见性授予…",
  "Held in the outbox for your approval ({why})": "已放入发件箱等你审批({why})",
  "Needs approval: {why}": "需要审批: {why}",
  "Nobody yet — every agent is hidden from it by default.": "还没有人 —— 默认对每个 agent 都是隐藏的。",
  "Not sent: {why}": "未发送: {why}",
  "Only used when the time zone above is set.": "只在上面设置了时区时生效。",
  "Only used when the time zone above is set. Mon–Fri.": "只在上面设置了时区时生效。周一至周五。",
  "Original text (before your edit)": "原文(你编辑之前)",
  "Outbox": "发件箱",
  "Outbox ({n} awaiting)": "发件箱({n} 条待审批)",
  "Outbox: a message with a link always needs your approval": "发件箱: 带链接的消息一律需要你审批",
  "Outbox: a message with an attachment always needs your approval": "发件箱: 带附件的消息一律需要你审批",
  "Outbox: working hours end (HH:MM)": "发件箱: 工作时间结束(HH:MM)",
  "Outbox: working hours start (HH:MM)": "发件箱: 工作时间开始(HH:MM)",
  "Outbox: working-hours time zone (empty = the off-hours guard is off)": "发件箱: 工作时间的时区(留空 = 非工作时间护栏关闭)",
  "Outbox…": "发件箱…",
  "Pick an agent or a group.": "先选一个 agent 或一个组。",
  "Policy saved": "策略已保存",
  "Policy: direct — your reply is sent at once unless a guard (link, attachment, off-hours) sends it to the outbox for approval.": "策略: 直接发送 —— 你的回复会立即发出, 除非某条护栏(链接、附件、非工作时间)把它送进发件箱等待审批。",
  "Policy: review — your reply waits in the outbox for your approval.": "策略: 审批 —— 你的回复会在发件箱里等你批准。",
  "Proposal {state}": "提案 {state}",
  "Proposals awaiting your approval — open the conversation or the Outbox.": "有提案在等你审批 —— 打开这个对话或发件箱。",
  "Propose": "提议",
