  "Receipt recorded": "回执已记录",
  "Reject": "拒绝",
  "Rejected": "已拒绝",
  "Reject…": "拒绝…",
  "Sending policy": "发送策略",
  "Sent": "已发送",
  "Sent directly: the channel policy is \"direct\" and no guard applied.": "已直接发送: 这个频道的策略是“直接发送”且没有护栏触发。",
  "The outbox is not available.": "发件箱不可用。",
  "This send is never retried automatically. Check the conversation on the platform before proposing it again.": "这次发送不会被自动重试。再次提议之前, 先去平台上看一眼这个对话。",
  "Who can see this conversation": "谁能看见这个对话",
  "Why: {ref}": "起因: {ref}",
  "Will send as {who}": "将以 {who} 的身份发送",
  "Just appeared or moved — read it first, then decide": "刚出现或刚移动过——请先读一遍再决定",
  "An invisible character that changes how the text reads — it is sent as it is": "一个会改变文字显示方式的不可见字符——它会原样发送",
  "In reply to": "回复的是",
  "To": "收件人",
