  "The text carries invisible characters that change how it reads ({list}) — each is shown as a mark and is sent as it is": "正文含有会改变阅读顺序的不可见字符({list})——每个都显示为一个标记，并会原样发送",
  "This proposal changed since the card was drawn — nothing was sent; read it again, then decide": "这条提议在卡片显示之后发生了变化——没有发送任何内容；请重新阅读后再决定",
