  "{who} asks: {why}": "{who} 请求: {why}",
  "sending needs the send permission on the connected app — reconnect (Re-authorize) to allow drafts and sending; some apps must also enable their send permissions and publish a version first": "发送需要已连接应用上的发送权限 —— 重新连接(重新授权)以允许起草与发送; 有些应用还需先启用其发送权限并发布一个版本",
