  "Leading and trailing whitespace is trimmed before saving.": "保存前会去掉首尾空白。",
  "Fake channel (test adapter)": "测试频道(测试适配器)",
  "Any value of at least 4 characters; the fake adapter talks to nothing. A key containing \"fail\" makes Test fail (the fixture switch).": "任意至少 4 个字符的值; 测试适配器不与任何服务通信。含有“fail”的密钥会让测试失败(测试夹具开关)。",
  "Region": "区域",
  "Optional; echoed back unchanged.": "可选; 原样回显。",
  "The test channel has no console; nothing needs to be registered anywhere.": "测试频道没有控制台; 无需在任何地方登记。",
  "A key of at least 4 characters is saved below, or the cluster provides one": "下方已保存至少 4 个字符的密钥, 或由集群提供",
  "The key does not contain the word \"fail\" (that is the Test fixture switch)": "密钥不含“fail”一词(那是测试夹具开关)",
  "Checks the resolved key's shape and the fixture switch. Zero network: the fake adapter has no vendor.": "检查解析出的密钥形状与夹具开关。零网络: 测试适配器没有供应商。",
  "This proves nothing about any vendor — the fake adapter has none. It shows that the value you saved is the value the adapter resolves.": "这不能证明任何供应商侧的事 —— 测试适配器没有供应商。它只说明你保存的值就是适配器解析到的值。",
  "Used by the test channel": "测试频道在用",
  "App ID": "App ID",
  "Developer Console → Credentials & Basic Info.": "开发者后台 → 凭证与基础信息。",
  "App Secret": "App Secret",
  "Same page. It is only ever written here, never read back.": "同一页面。只会在这里写入, 永远不会回显。",
  "Developer Console → Security Settings → Redirect URLs. It must match byte for byte.": "开发者后台 → 安全设置 → 重定向 URL。必须逐字节一致。",
  "The redirect URL above is registered in that list": "上面的重定向 URL 已登记在那个列表里",
  "The scopes im:message and im:message.send_as_user are granted": "已授予 im:message 与 im:message.send_as_user 权限",
  "The app has a PUBLISHED version": "应用已有一个已发布的版本",
  "Exchanges this app id / secret pair for a tenant token once. Reads no conversation, sends no message.": "用这对 app id / secret 换取一次租户令牌。不读任何会话, 不发任何消息。",
  "This only proves the app id / secret pair is right. The consent page also needs the three items above — missing any of them fails on the consent page, not on this call.": "这只证明 app id / secret 这一对是正确的。授权页还需要上面三项 —— 缺任何一项都会在授权页失败, 而不是在这次调用里。",
  "Used by the Lark / 飞书 channel": "Lark / 飞书频道在用",
  "OAuth client ID": "OAuth 客户端 ID",
  "Only when using your own client.": "仅在使用你自己的客户端时需要。",
  "Checks the client id / secret shape and builds the authorization URL. A Google OAuth client cannot be exchanged for anything on its own (no client-credentials grant), so the real verdict is the OAuth round trip.": "检查客户端 id / 密钥的形状并构造授权 URL。Google OAuth 客户端本身换不到任何东西(没有 client-credentials 授权), 真正的判决来自 OAuth 往返。",
  "Shape only. Whether the consent succeeds, and how long the refresh token lives, depends on the client's verification status.": "只检查形状。授权能否成功、刷新令牌能活多久, 取决于客户端的审核状态。",
  "Used by the Gmail channel": "Gmail 频道在用",
  "License key": "授权码",
  "Checks the key's shape, offline. No key passes: the free CloakBrowser needs none.": "离线检查授权码的格式。没有授权码也算通过:免费版 CloakBrowser 不需要。",
  "Shape only. The seat tier is read back from the first real launch, not from this check.": "只检查形状。席位档次要等第一次真正启动才能读到, 不是这次检查。",
  "no key of your own and no cluster default": "没有你自己的密钥, 也没有集群默认值",
  "The test channel talks to nothing; any key of at least 4 characters works.": "测试频道不连接任何服务; 任何至少 4 个字符的密钥都可以。",
  "The tenant app this account signs in through. A token is bound to the app it was issued under — switching the app means signing in again.": "这个账号登录所用的租户应用。token 绑定在签发它的应用上 —— 换应用就要重新登录。",
  "The Google OAuth client this account signs in through. A refresh token is bound to the client it was issued under — switching the client means signing in again.": "这个账号登录所用的 Google OAuth 客户端。refresh token 绑定在签发它的客户端上 —— 换客户端就要重新登录。",
  "this integration's client is chosen per account — edit the account to choose one": "这个集成的客户端按账号选择 —— 编辑账号来选一个",
  "this account's own client is incomplete ({fields}) — edit the account": "这个账号自己的客户端不完整 ({fields}) —— 编辑账号",
  "this account's own client secret cannot be decrypted with the current key file — edit the account and enter it again": "当前密钥文件无法解密这个账号自己的客户端 secret —— 编辑账号并重新输入",
  "this account's client could not be moved onto the account ({why})": "这个账号的客户端没能迁移到账号上 ({why})",
  "the cluster provides no default for this integration": "集群没有为这个集成提供默认值",
