  "no keys of your own are saved for this integration": "这个集成没有保存你自己的密钥",
  "the credential key ({key}) is not one this instance offers": "凭据键({key})不是本实例提供的",
  "the cluster provides {n} presets and none is the preferred one — choose one": "集群提供了 {n} 个预设, 没有一个是首选 —— 请选一个",
  "the stored keys ({fields}) cannot be decrypted with the current key file": "存下的密钥({fields})无法用当前密钥文件解密",
  "the integrations store could not be read": "集成存储无法读取",
  "the cluster default this row used ({from}) was re-keyed to {to} — the only default this instance offers": "这一行使用的集群默认值({from})已改名为 {to} —— 本实例提供的唯一默认值",
  "no integration store on this instance": "本实例没有集成存储",
