  "Brand": "品牌",
  "feishu = 飞书 (open.feishu.cn), lark = Lark international (open.larksuite.com) — the console the app was created in.": "feishu = 飞书(open.feishu.cn), lark = Lark 国际版(open.larksuite.com) —— 即创建应用所在的后台。",
  "Include query": "纳入查询",
