  "The Cloud Pub/Sub topic Gmail publishes mailbox changes to (users.watch). Grant gmail-api-push@system.gserviceaccount.com the Publisher role on it. Only read when push is enabled.": "Gmail 发布邮箱变更的 Cloud Pub/Sub 主题(users.watch)。请把 Publisher 角色授予 gmail-api-push@system.gserviceaccount.com。仅在推送启用时读取。",
