  "When an agent proposes a reply with vibespace-channels, it waits here for you to approve, edit or reject it.": "Agent 用 vibespace-channels 提议回复后，会在这里等你批准、编辑或拒绝。",
  "Nothing is waiting for your approval.": "没有等你审批的提案。",
  "Group · {name}": "组 · {name}",
