  "add at least one rule": "至少添加一条规则",
  "a filter may hold at most {n} rules": "一个过滤器最多 {n} 条规则",
  "Channel {label}: {n} consecutive failed passes ({code})": "频道 {label}：连续 {n} 次拉取失败（{code}）",
  "Channel {label}: its refreshed sign-in could not be saved to disk ({error})": "频道 {label}：刷新后的登录没能写入磁盘（{error}）",
  "Outbox: a send to {title} has an UNKNOWN outcome": "发件箱：发往 {title} 的一次发送结果未知",
  "A send in {adapter} · {title}: the adapter did not answer whether the message landed. It is NOT retried automatically — a duplicate in somebody else's room is worse than asking.": "{adapter} · {title} 里的一次发送：适配器没有回答消息是否送达。不会自动重试 —— 在别人的房间里发重复消息比问一句更糟。",
  "Check the conversation on the platform; the Outbox window shows the proposal.": "请到平台上查看这个对话；发件箱窗口里能看到这条提案。",
  "Proposals awaiting approval in {title}": "{title} 有提案等你审批",
  "{n} proposal(s) awaiting your approval in {adapter} · {title}.": "{adapter} · {title} 有 {n} 条提案等你审批。",
  "Latest ({who}): \"{text}\"": "最新（{who}）：“{text}”",
  "Latest (your own draft): \"{text}\"": "最新（你自己的草稿）：“{text}”",
  "Open the Outbox (rail → Channels → Outbox) or the conversation window to approve, edit or reject. This item is retracted by the channels engine when the last proposal leaves awaiting-approval.": "打开发件箱（侧栏 → 频道 → 发件箱）或对话窗口来批准、编辑或拒绝。最后一条提案离开“等你审批”状态时，频道引擎会自动撤回这一项。",
  "{agent} requests access to {title}": "{agent} 请求访问 {title}",
  "Agent session {name} ({id}) asks to see {adapter} · {title}.": "Agent 会话 {name}（{id}）请求查看 {adapter} · {title}。",
  "Reason: {reason}": "理由：{reason}",
  "Approve or deny from the conversation's Reach dialog (rail → Channels → row menu → Reach…). Approving grants that ONE session visibility on that ONE conversation; group defaults are untouched.": "在这个对话的“可见性与策略”对话框里批准或拒绝（侧栏 → 频道 → 行菜单 → 可见性与策略…）。批准只让这一个会话看到这一个对话；组的默认设置不变。",
  "Give each session its own agent browser": "每个会话用自己的 agent 浏览器",
  "ON (default): a session that runs the agent-browser CLI gets its own browser — its own tabs, its own cookies and its own daemon — so two agents stop stealing each other's window and `close --all` can only close the caller's own. Costs four environment variables at spawn and nothing else: no extra VibeSpace process. OFF: sessions fall back to the single shared profile named by ~/.agent-browser/config.json, which is what every agent used before. Applies to sessions started after the change; a running session keeps the browser it has — and one that has none (it started while this was off, or before the feature) gets its own at its next browser command.": "开(默认): 跑 agent-browser CLI 的会话拿到属于它自己的浏览器 —— 自己的标签页、自己的 cookie、自己的守护进程, 于是两个 agent 不再互相抢窗口, `close --all` 也只能关掉调用者自己的。代价就是 spawn 时的四个环境变量, 没有额外的 VibeSpace 进程。关: 会话回落到 ~/.agent-browser/config.json 点名的那一个共享 profile, 也就是以前所有 agent 用的那个。只对改动之后新开的会话生效; 已经在跑的会话保持它已有的浏览器 —— 还没有浏览器的会话(在关闭期间或此功能之前启动的)会在它下一条浏览器命令时拿到自己的。",
  "Close an idle agent browser after (ms)": "agent 浏览器空闲多久后关闭(毫秒)",
  "How long an agent's browser may sit idle before its daemon shuts itself down. Set explicitly because the installed CLI has NO default (and newer ones exempt browsers with a visible window), so nothing else would ever reclaim the browsers this feature creates — one per browsing session instead of one per machine. 0 = never shut down, which is the CLI's own meaning and a real choice; anything unreadable falls back to 15 minutes.": "agent 的浏览器空闲多久后, 它的守护进程自行关闭。显式设置是因为已安装的 CLI 根本没有默认值(而新版本会豁免带可见窗口的浏览器), 于是没有任何东西会去回收这个功能创造出来的浏览器 —— 从整台机器一个变成每个浏览会话一个。0 = 永不关闭(这是 CLI 自己的含义, 也是一个真实的选择); 读不出来就回落到 15 分钟。",
  "Show the agent browser window": "显示 agent 浏览器窗口",
  "Inherit from ~/.agent-browser/config.json": "沿用 ~/.agent-browser/config.json",
  "Whether an agent's browser draws a real window on this machine's desktop. Unset (default): whatever your own ~/.agent-browser/config.json says. A visible window per session is one framebuffer per session and, on the installed CLI, is also exempt from the idle timeout above.": "agent 的浏览器会不会在本机桌面上画出一个真窗口。不设(默认): 听你自己的 ~/.agent-browser/config.json。每个会话一个可见窗口 = 每个会话一块 framebuffer, 而且在已安装的 CLI 上它还会被上面那个空闲超时豁免。",
  "This machine has no desktop session now — with the window setting unset, an agent's browser runs in a hidden window (the live view can still take over)": "这台机器现在没有桌面会话——窗口设置未设置，agent 的浏览器在隐藏窗口中运行（实时视图仍可接管）",
  "This machine has no desktop session now — the window setting says Headless, so an agent's browser runs headless": "这台机器现在没有桌面会话——窗口设置为无界面，agent 的浏览器以无界面方式运行",
  "Show the window": "显示窗口",
