  "Adopted as {label}": "已收编为 {label}",
  "Move it beside itself and list it below — nothing is deleted until you click Delete permanently": "挪到它旁边并列在下方 —— 在你点击“永久删除”之前什么都不会被删除",
  "Set aside {name}?": "搁置 {name}?",
