  "The session that held this window is no longer live — the lease is free for the next agent": "持有这个窗口的会话已不在线 — 租约空出来给下一个 agent",
  "The agent session holding this window (one holder per window)": "持有这个窗口的 agent 会话(每个窗口只有一个持有者)",
