  "Take over this window — the agent’s actions are refused and nothing is injected until you hand back": "接管这个窗口 — 在你交还之前 agent 的动作会被拒绝, 也不会注入任何输入",
  "You are driving this window directly — the agent is not injecting until you hand back": "你正在直接操作这个窗口 — 在你交还之前 agent 不会注入任何输入",
