  "{label} — agent window": "{label} — agent 窗口",
  'Desktop app display backend order': '桌面应用画面后端顺序',
  'Comma-separated rung ids that reorder the picture-backend ladder for NEW desktop apps on this instance, e.g. "vnc-display, xpra" to keep the whole-display rung first. Empty = installed order (xpra > vnc-display > desktop-singleton). Unknown ids are ignored; a running app keeps the backend it started with.': '逗号分隔的画面后端 id，用于为本实例上新建的桌面应用重排画面后端阶梯，例如 "vnc-display, xpra" 让整显示级优先。留空 = 安装顺序（xpra > vnc-display > desktop-singleton）。未知 id 会被忽略；已在运行的应用保持它启动时的后端。',
  'Keyboard input for the application': '应用程序的键盘输入',
  'Active on another client': '正在另一个客户端上使用',
  'Resume here': '在此继续',
  'Make this window the active one — the other client is blocked until it resumes': '让这个窗口成为活跃窗口 — 另一个客户端将被挡住，直到它在那边继续',
  'Could not resume here': '无法在此继续',
  'Copied in the app — click to copy': '应用内已复制 — 点击复制到本机',
  'The application put text on its clipboard; this page cannot write yours without a click (plain http)': '应用程序把文本放到了它的剪贴板；在明文 http 下本页面需要你点击一下才能写入你的剪贴板',
  'Copied to your clipboard': '已复制到你的剪贴板',
  'Could not copy — select the text in the app and press Ctrl+C again': '复制失败 — 请在应用里选中文本再按一次 Ctrl+C',
  'The application closed its window': '应用程序关闭了它的窗口',
  'The application is not connected': '应用程序尚未连接',
  'Pasted into the application': '已粘贴到应用程序',
  'Waiting for the application window…': '等待应用程序窗口…',
  "Priority": "优先级",
  "High priority": "高优先级",
  "Low priority": "低优先级",
  "Backlog cleanup nudge: items per session": "待办清理提醒：每会话条目数",
  "When one session holds this many open backlog items (claimed or parked by it), its backlog commands and its per-turn backlog note ask it to finish, drop or merge items before parking more. 0 = never.": "当一个会话持有这么多未完成的待办条目（由它认领或搁置）时，它的待办命令和每轮待办提示会要求它先完成、丢弃或合并条目，再搁置新的。0 = 从不提醒。",
  "Scaled to fit — the app needs at least {w}×{h}": "已缩放以适应 — 应用至少需要 {w}×{h}",
  "The scale this app was started at (Settings → Desktop app scale). A change takes effect when the app is launched again.": "此应用启动时的缩放（设置 → 桌面应用缩放）。修改后需重新启动应用才会生效。",
  "xpra streams each app window as pixels; text stays crisp at your screen’s scale": "xpra 把每个应用窗口作为像素流传输；文字按你屏幕的缩放渲染，保持清晰",
  "Auto (this screen)": "自动（当前屏幕）",
  "Desktop app scale (xpra)": "桌面应用缩放（xpra）",
  "Reply": "回复",
  "Reply…": "回复…",
  "Send reply (Enter) · newline (Shift+Enter)": "发送回复（Enter）· 换行（Shift+Enter）",
  "This conversation has ended — sending reopens it with this reply as its first message": "这个对话已结束；发送会重新打开它并把这条回复作为第一条消息",
  "Reopen and send": "重新打开并发送",
  "Reopen the conversation and send this reply (Enter) · newline (Shift+Enter)": "重新打开这个对话并发送这条回复（Enter）· 换行（Shift+Enter）",
  "Reopen and send \"{label}\"": "重新打开并发送「{label}」",
