  "Copied: the type, the OAuth client, the query, the push claim, the sender line. NOT copied: the token (a login is one person’s consent), refresh overrides, access grants and notifications, reach grants, the message log — the copy signs in on its own.": "会复制：类型、OAuth 客户端、查询、推送声明、发件人说明行。不会复制：令牌（登录是某个人的授权）、刷新周期设置、访问授权与通知、可见范围授权、消息日志 — 副本需要自己登录。",
