  "Delivers every waiting notice now, as one message — it joins the turn already running; if that turn cannot take it, it runs as its own billed turn right after": "把所有在等的通知现在作为一条消息交给它 —— 并入正在进行的这一轮; 如果这一轮接不下, 它会紧接着作为单独的一轮计费运行",
  "Delivers every waiting notice now, as one message — it starts a billed turn for this agent": "把所有在等的通知现在作为一条消息交给它 —— 会为这个 agent 开始一轮计费的对话",
