  "Not handed over — this agent’s process predates mid-turn notifications; the notices ride its next prompt (restart the session to receive them mid-turn)": "没有交出去 —— 这个 agent 的进程早于回合中通知; 这些通知随它的下一条提示送达 (重启会话即可在回合中收到)",
