  "This agent is mid-turn — a message typed into a running turn carries no group message; they ride its next turn after this one ends, whoever starts it, or at once when a member @mentions it": "这个 agent 正在一轮中 — 在进行中的一轮里输入的消息不携带群消息; 它们随本轮结束后的下一轮送达（不论由谁开启），有成员 @ 它时则立即送达",
