  "The CloakBrowser browser program (its chrome file), for when it was installed some other way. Leave it empty to use the one installed from Manage agents.": "CloakBrowser 浏览器程序(它的 chrome 文件),用于你用别的方式装过它的情况。留空则使用在管理 Agents 里安装的那一个。",
