  "Nobody can use it now: its list could not be read — choose Change… to set it again": "现在没有会话能使用它：它的名单无法读取 — 请点“更改…”重新设置",
  "Only the conversations and Task Groups listed here can use it. Picking it for another conversation (New Session, Session properties) adds that conversation.": "只有这里列出的会话和任务组能使用它。在别的会话里选它（新建会话、会话属性）会把那个会话加进来。",
  "Who can use {label}?": "谁能使用 {label}？",
  "Only these": "仅以下会话和任务组",
  "Pick conversations and Task Groups. A Task Group means every conversation in it — bound to it or started in its folders — now or later.": "选择会话和任务组。选任务组就是选它里面的每个会话——绑定到它的或在它的文件夹里启动的——现在和以后的都算。",
  "Add a conversation or Task Group…": "添加会话或任务组…",
