  "{n} conversation(s) using it now will lose it when you save (their pages in it close).": "现在正在使用它的 {n} 个会话会在保存后失去它（其中的页面会关闭）。",
  "made it · not running now": "创建了它 · 当前未运行",
  "Who can use {label}: {list}": "谁能使用 {label}：{list}",
