  "“{name}” has no browser of its own yet — restart it (Terminate → Resume), then add it": "“{name}”还没有自己的浏览器 — 先重启它（终止 → 恢复），再添加",
  "That conversation is not running any more — pick it again from the list": "那个会话已经不在运行 — 请从列表里重新选择",
  "That Task Group no longer exists — pick another one": "那个任务组已不存在 — 请选择别的",
  "That conversation can no longer be added — pick it again from the list": "那个会话已无法添加 — 请从列表里重新选择",
