  "{who} will not be woken here — at most 0 times a day.": "{who} 在这里不会被唤醒 —— 每天最多 0 次。",
  "{who} will get one digest every {n} minutes of {what} {where}, woken at most {cap} times a day.": "{where}的{what}每 {n} 分钟汇总成一份摘要发给 {who}，每天最多唤醒 {cap} 次。",
  "{who} will be woken right away for {what} {where}, at most {cap} times a day.": "{where}的{what}会立即唤醒 {who}，每天最多 {cap} 次。",
  "Who may read and act here?": "谁可以在这里阅读和操作？",
  "The whole account — {label}": "整个账号 —— {label}",
  "The conversations matching a rule — {label}": "符合规则的会话 —— {label}",
  "May draft replies (you approve)": "可以起草回复（由你批准）",
  "May reply directly": "可以直接回复",
  "(A digest cannot be capped at 0 — it is read as 1. Set at least 1 to save.)": "（摘要不能把上限设为 0 —— 会按 1 处理。至少设为 1 才能保存。）",
  "This notification's rule is missing from the store — nobody is woken by it until you pick the messages again.": "这条通知的规则已不在存储里 —— 在你重新选定消息之前，它不会唤醒任何人。",
  // lane live-input (2026-09-27): paste + IME into the agent's browser, copy out, the fit chip and the recording chip in plain words
  "Copied in the page — click to copy": "已在网页里复制 — 点这里放进剪贴板",
  "Text was copied in the agent’s browser. It goes on your clipboard only by your own copy key, or by this click — click to copy it.": "agent 的浏览器里复制了文字。只有你自己按的复制键、或这里的一次点击，才会把它放进你的剪贴板 — 点击即可复制。",
  "the browser takes at most 3 characters in one key": "浏览器一次按键最多只接受 3 个字符",
  "it is more text than one paste may carry": "文字太长，超过了一次粘贴的上限",
  "there was nothing to type": "没有可输入的内容",
  "({n} characters reached the page first)": "（前 {n} 个字符已经进了网页）",
  "sent — a line break at the very end could not be typed": "已发送 — 末尾的一个换行无法输入",
  "The page will fit this window once the other window hands back": "等另一个窗口交还控制后，网页就会适配这个窗口",
  "The page now fits this window": "网页现在适配这个窗口了",
  "not sent — a lone line break cannot be typed into the page (press Enter instead)": "未发送 — 单独一个换行无法输入网页（请直接按回车）",
  "nothing was copied — the page gave no text (nothing selected, a password field, or a frame from another site)": "没有复制到内容 — 网页没有给出文字（没有选中内容、是密码框，或在其他网站的嵌入框里）",
  "nothing was copied — no text is selected in the page": "没有复制到内容 — 网页里没有选中文字",
  "copied the first {n} characters to your clipboard": "已把前 {n} 个字符复制到你的剪贴板",
  "copied to your clipboard": "已复制到你的剪贴板",
  "copied in the page — use the button on the bar to put it on your clipboard": "已在网页里复制 — 用栏上的按钮把它放进剪贴板",
  "Could not copy — select the text in the page and press Ctrl+C again": "复制失败 — 请在网页里重新选中文字，再按一次 Ctrl+C",
  "The agent set this page to the {device} size ({w}×{h}).": "Agent 把这个网页设成了 {device} 的尺寸（{w}×{h}）。",
  "The agent set this page to {w}×{h}.": "Agent 把这个网页设成了 {w}×{h}。",
  "Agent’s size {w}×{h} · Fit here": "Agent 设定的尺寸 {w}×{h} · 点此适配本窗口",
  "This window shows it scaled. Click to make the page fit this window again.": "这个窗口按比例缩放显示它。点击后网页会重新适配这个窗口。",
  "Sized for your other window · Fit here": "网页大小跟随你的另一个窗口 · 点此适配本窗口",
