  "Sized for another device · Fit here": "网页大小跟随另一台设备 · 点此适配本窗口",
  "Sized for another window · Fit here": "网页大小跟随另一个窗口 · 点此适配本窗口",
  "your other window showing this browser": "你的另一个窗口",
  "another tab or window of yours on this device": "你在这台设备上的另一个标签页或窗口",
