  "another window showing this browser": "另一个正在显示它的窗口",
  "The page is {w}×{h} to fit the window of whoever is driving it ({place}).": "网页现在是 {w}×{h}，是照着正在操作它的那个窗口（{place}）的大小调的。",
  "The page is {w}×{h} to fit {place}.": "网页现在是 {w}×{h}，是照着{place}的大小调的。",
