  "its browser keeps closing; VibeSpace stopped starting it (Stop resets it)": "它的浏览器反复关闭，VibeSpace 已不再启动它（点“停止”可重置）",
  "its folder is held by another browser": "它的文件夹正被另一个浏览器占用",
