  "the conversation is not running — resume it first": "该对话没有在运行——请先恢复对话",
  "Could not resume the browser: {why}": "无法恢复浏览器：{why}",
  "The browser is running — reconnecting": "浏览器正在运行——正在重新连接",
  "Resumed — {n} tab(s) reopened": "已恢复——重新打开了 {n} 个标签页",
  "Resumed — the browser runs again": "已恢复——浏览器重新运行",
  "{n} tab(s) not reopened: {why}": "{n} 个标签页未能重新打开：{why}",
  "Hand the browser back for the agent’s next turn": "把浏览器交还给 agent 的下一轮",
  "A note for the agent (optional)": "给 agent 的说明（可选）",
  "e.g. I logged in — continue from the cart": "例如：我已登录——从购物车继续",
  "Could not hand the browser back: {why}": "无法交还浏览器：{why}",
  "Handed back — the agent reads your note and the tabs with its next turn (nothing is sent now)": "已交还——agent 会在下一轮读到你的说明和标签页（现在不会发送任何内容）",
  "Already handed back — the agent reads it with its next turn": "已经交还过了——agent 会在下一轮读到它",
  "Stopped — its {n} tab(s) are kept (not its logins: this browser is fenced to allowed domains). Resume reopens them": "已停止——它的 {n} 个标签页已保留（登录未保留：这个浏览器被限定在允许的域名内）。恢复会重新打开它们",
  "Stopped — its {n} tab(s) are kept (not its logins). Resume reopens them": "已停止——它的 {n} 个标签页已保留（登录未保留）。恢复会重新打开它们",
  "Stopped — its logins are kept. Resume starts it again; the agent’s next command also does": "已停止——它的登录已保留。恢复会重新启动它；agent 的下一条命令也会",
  "Stopped — its {n} tab(s) and its logins are kept. Resume reopens them; the agent’s next command also starts it again": "已停止——它的 {n} 个标签页和登录都已保留。恢复会重新打开它们；agent 的下一条命令也会重新启动它",
  "Could not resume the browser": "无法恢复浏览器",
  "Resume the conversation to reopen its browser": "恢复该对话即可重新打开它的浏览器",
  "The agent’s": "agent 的",
  "The agent is here": "agent 在这里",
  "Yours": "你的",
  "Another conversation’s": "其他对话的",
  "Nobody’s": "无主",
  "The agent’s tab — take over to switch or close it; the agent is told at the handback": "agent 的标签页——接管后可以切换或关闭它；交还时会告诉 agent",
  "Your tab": "你的标签页",
  "Your own tab (Browse yourself)": "你自己的标签页（自己浏览）",
  "{name}’s tab — watch it here (view only); open its own live view to drive it": "{name} 的标签页——可以在这里观看（只看不动）；要操作它，请打开它自己的实时视图",
  "Watch this tab — view only; nobody’s tab moves": "观看这个标签页——只看不动，谁的标签页都不会被切换",
