  "Nobody’s tab": "无主的标签页",
  "Nobody’s tab — open Browse yourself on this profile to take it": "无主的标签页——在这个配置上打开“自己浏览”即可接手",
  "Switch to your own tab from your browsing window": "请在你的浏览窗口里切换到自己的标签页",
  "The browser is not answering — Restart it from the Browser panel": "浏览器没有响应——请在浏览器面板中重启它",
  "Not answering since {clock}": "自 {clock} 起无响应",
  "browser not answering": "浏览器无响应",
  "{label} has not answered since {clock}": "{label} 自 {clock} 起没有响应",
  "The browser stopped answering (it is hung, not busy) — Restart stops it and starts it again; logins stay in the profile, its tabs are re-opened and every conversation using it is told": "浏览器已停止响应（是卡死，不是忙）——重启会关闭并重新启动它；登录状态保留在配置文件中，标签页会重新打开，正在使用它的每个对话都会收到通知",
  "The browser froze because its log pipe filled and nothing read it (a fault of the browser driver 0.38.1, fixed in 0.38.2) — Restart starts it again on the updated driver; logins stay in the profile, its tabs are re-opened and every conversation using it is told": "浏览器卡死是因为它的日志管道写满了而没人读取（浏览器驱动 0.38.1 的缺陷，0.38.2 已修复）——重启会用更新后的驱动重新启动它；登录状态保留在配置文件中，标签页会重新打开，正在使用它的每个对话都会收到通知",
  "Restart the browser that stopped answering — logins stay in the profile, its tabs are re-opened": "重启已停止响应的浏览器——登录状态保留在配置文件中，标签页会重新打开",
  "The tabs could not be read just now — try again": "暂时读不到标签页——请重试",
  "That tab is gone": "那个标签页已经不在了",
  "Take over to switch or close the agent’s tabs": "接管后可以切换或关闭 agent 的标签页",
  "This is the agent’s only tab — Close all tabs (quit this browser) ends it": "这是 agent 唯一的标签页——“关闭全部标签页（退出这个浏览器）”会结束它",
  "This is your only tab — press Close to end your browsing": "这是你唯一的标签页——按“关闭”结束你的浏览",
  "This browser keeps each conversation’s tabs apart — its tabs are switched and closed by the agent": "这个浏览器把每个对话的标签页分开——它的标签页由 agent 切换和关闭",
  "Could not do that": "无法完成这个操作",
  "Switch to this tab": "切换到这个标签页",
  "Close tab": "关闭标签页",
  "Close all…": "全部关闭…",
  "Close all tabs (quit this browser)…": "关闭全部标签页（退出这个浏览器）…",
  "{n} more tab(s) of this browser": "这个浏览器还有 {n} 个标签页",
  "Could not close the tab: {why}": "无法关闭标签页：{why}",
  "Could not switch tabs: {why}": "无法切换标签页：{why}",
  "the live view is not connected": "实时视图没有连接",
  "Closed “{title}” — the agent is told when you hand back": "已关闭“{title}”——交还时会告诉 agent",
  "Close all tabs of “{name}”?": "关闭“{name}”的全部标签页？",
  "This quits “{name}” — every tab of it closes. Its logins are kept.": "这会退出“{name}”——它的每个标签页都会关闭。登录会保留。",
  "This quits “{name}” — every tab of it closes. Its logins are kept; the agent’s next browser command starts it again.": "这会退出“{name}”——它的每个标签页都会关闭。登录会保留；agent 的下一条浏览器命令会重新启动它。",
  "This server holds {count} open file handles — {pct}% of its limit ({soft}). By kind: {kinds}. Past the limit, saving and new connections fail.": "此服务器持有 {count} 个打开的文件句柄 — 已达上限（{soft}）的 {pct}%。按类型：{kinds}。超过上限后，保存和新连接都会失败。",
  "The file system under {mount} ({fstype}) refused to open a file (too many open files) while this server holds {held} file handles — the file system's own process ran out. Raise its limit (for a mount unit: LimitNOFILE in a drop-in), not this server's.": "{mount} 下的文件系统（{fstype}）拒绝打开文件（打开的文件过多），而此服务器只持有 {held} 个文件句柄 — 是该文件系统自己的进程用完了句柄。请提高它的上限（挂载单元：在 drop-in 里设置 LimitNOFILE），而不是此服务器的。",
  "Reconnect a silent conversation after (minutes)": "对话静默多久后自动重连（分钟）",
  "When a conversation has sent VibeSpace nothing for this long while its agent is still working (its output file or its API requests say so), VibeSpace reconnects to its output by itself and shows what it missed as caught up — nothing is re-run. 0 turns this off.": "当一个对话在这么长时间里没有给 VibeSpace 发来任何输出，而它的 agent 仍在工作（它的输出文件或 API 请求表明这一点）时，VibeSpace 会自动重新连接它的输出，并把错过的内容作为补上的记录显示 — 不会重新执行任何东西。设为 0 即关闭。",
  "Show page-size changes": "显示页面尺寸变化",
  "Live view fitted ×{n} · {size} (last)": "实时视图已适配 ×{n} · {size}（最后一次）",
  "Live view fitted · {size}": "实时视图已适配 · {size}",
  "{n} page-size change(s)": "{n} 次页面尺寸变化",
  "page-size frames: {size}": "页面尺寸帧：{size}",
  "Every resize or move of the live view fits the page to it and is recorded. Off: consecutive page-size changes are one dim row. On: each is its own row with its frames.": "每次调整或移动实时视图，页面都会被适配到它并被记录下来。关闭：连续的页面尺寸变化合并为一行灰色记录。开启：每一次都单独成行并带有画面。",
  "{n} page-size change(s) between {from} and {to} — the live view was resized or moved and the page fitted to it; click for the last one.": "{from} 到 {to} 之间有 {n} 次页面尺寸变化 —— 实时视图被调整或移动，页面随之适配；点击查看最后一次。",
