  "The company presets file {file} could not be read ({code}) — it offers no presets until it is fixed.": "公司预设文件 {file} 无法读取（{code}）—— 修好之前它不提供任何预设。",
  "Company presets: none — ask your admin.": "公司预设：无 —— 请联系你的管理员。",
