  "The agent did not accept this at once; VibeSpace posts it again when its turn ends and on a schedule — Hand over now delivers it this instant": "agent 没有立刻接收这条通知；VibeSpace 会在它本轮结束时以及按计划再次投递 — 「立即交接」则此刻就送达",
  "{n} waiting notice(s) handed over — {why}": "已交接 {n} 条等待中的通知 — {why}",
  "they arrived while this conversation was not running": "它们到达时这个对话没有在运行",
  "the agent did not accept them at once (busy or unreachable) — delivered now": "agent 当时没有立刻接收（忙碌或无法连通）— 现在已送达",
  "their delivery was being retried — delivered now": "它们正在重试投递 — 现在已送达",
  "the server stopped while they were being sent — some may have reached the agent already, delivered again now": "发送途中服务器停止了 — 其中一些可能已经送达过 agent，现在再次送达",
