  "they were held until now": "它们一直被保留到现在",
  "the conversation was not running; delivered when it next resumes": "对话当时没有在运行；它下次恢复时送达",
  "the agent did not accept it at once; posted again when its turn ends": "agent 没有立刻接收；它本轮结束时会再次投递",
  "the agent did not accept it (busy or unreachable); delivered with the conversation’s next prompt or a hand-over": "agent 没有接收（忙碌或无法连通）；随对话的下一条消息或一次交接送达",
  "they will arrive as a message when this turn ends": "它们会在本轮结束时作为一条消息送达",
  "retrying ({n} so far, {phase}, {busy})": "重试中（已 {n} 次，{phase}，{busy}）",
