  "Keeps this conversation's browser and its logins — Chromium on this computer.": "保留这个会话的浏览器和其中的登录状态——在本机上用 Chromium 运行。",
  "Runs on": "运行在",
  "Create and use it here": "创建并在此会话中使用",
  "Could not read which browsers this VibeSpace offers — {reason}": "无法读取这个 VibeSpace 提供哪些浏览器——{reason}",
  "Could not create the profile": "无法创建配置",
  "{label} keeps this conversation's logins — every conversation you allowed can use it": "{label} 保留了这个会话的登录状态——你允许的每个会话都能使用它",
  "{label} was created empty — the agent's next browser command opens it and you sign in there once": "{label} 已创建（空白）——agent 的下一个浏览器命令会打开它，你在里面登录一次即可",
  "Created {label}": "已创建 {label}",
  "A window on your desktop is shared with an agent from the window itself — it is not a profile.": "桌面上的窗口要从窗口本身共享给 agent——它不是一个配置。",
  "Runs only on the computer VibeSpace runs on — pick This computer to use it.": "只能在运行 VibeSpace 的电脑上使用——选择“本机”才能用它。",
  "Off until you allow agents to use windows on your desktop (Settings → Desktop apps).": "在你允许 agent 使用桌面窗口之前保持关闭（设置 → 桌面应用）。",
  "Can't be used in this version of VibeSpace.": "这个版本的 VibeSpace 还不能使用它。",
  "Installing… it can be chosen once it is done.": "正在安装……装好后就能选择。",
  "Not installed yet — install it first, then choose it.": "尚未安装——请先安装，再选择它。",
  "Connects to a browser that is already running with a debugging port — enter its port.": "连接到一个已开启调试端口、正在运行的浏览器——请填写它的端口。",
  "Runs at the vendor; it needs your key (⚙ → Integrations) before its first start.": "在服务商那里运行；首次启动前需要你的密钥（⚙ → 集成与密钥）。",
  "This computer": "本机",
  "Not connected right now.": "当前未连接。",
  "Its VibeSpace agent is too old to run a browser — update the agent on it.": "它上面的 VibeSpace 代理太旧，无法运行浏览器——请更新那台机器上的代理。",
  "This browser runs only on the computer VibeSpace runs on.": "这个浏览器只能在运行 VibeSpace 的电脑上使用。",
  "Give the profile a name.": "给配置起个名字。",
  "A profile with this name already exists — pick another name.": "已有同名配置——请换一个名字。",
  "Enter the port the browser listens on (1–65535).": "填写浏览器监听的端口（1–65535）。",
  "That machine is not paired with this VibeSpace any more — pick another.": "那台机器已不再与这个 VibeSpace 配对——请选择另一台。",
  "This browser can't be used in this version of VibeSpace.": "这个版本的 VibeSpace 还不能使用这个浏览器。",
  "Separate tabs can't be used here.": "这里不能使用独立标签页。",
