  "These commands run on {machine} as root:": "这些命令会以 root 身份在{machine}上运行：",
  "{app} is removed from {machine}": "已从{machine}卸载 {app}",
  "The apps on {machine} are refreshed": "{machine}上的应用已刷新",
  "The package source {app} is added to {machine}": "已给{machine}添加软件源 {app}",
  "The package source {app} is removed": "已移除软件源 {app}",
  "Your apps are back on {machine}": "你的应用已恢复到{machine}",
  "{name} proposed this.": "这是 {name} 提议的。",
  "An agent": "一个 agent",
  "Why: {why}": "原因：{why}",
  "{n} packages · {download} to download · {disk} on disk": "{n} 个包 · 需下载 {download} · 占用磁盘 {disk}",
  "Already installed — VibeSpace keeps it so it comes back after a rebuild.": "已经安装 — VibeSpace 会保留它，机器重建后它会回来。",
  "From: {origins}": "来源：{origins}",
