  "Packages ({n})": "包（{n}）",
  "After this machine is rebuilt, VibeSpace puts it back from its saved packages — about {s} s after the server starts.": "这台机器重建后，VibeSpace 会用保存的包把它装回来 — 服务器启动后大约 {s} 秒。",
  "Address: {uri}": "地址：{uri}",
  "Suites: {suites}": "发行版：{suites}",
  "Key fingerprint: {fpr}": "密钥指纹：{fpr}",
  "Compare the fingerprint with the one the publisher shows. Packages come from this source only when you install them later.": "请把指纹和发布者公布的指纹对照。只有你之后安装包时，才会从这个源获取。",
  "Removes: {pkgs}": "将卸载：{pkgs}",
  "Its packages stay (another of your apps uses them); only the record goes.": "它的包会保留（你的另一个应用在用）；只删除记录。",
  "{n} updates: {list}": "{n} 个更新：{list}",
  "Everything is up to date — Refresh still checks again and saves the packages.": "全部都是最新的 — 刷新仍会重新检查并保存这些包。",
  "never refreshed": "从未刷新",
