  "{n} updates · {ago}": "{n} 个更新 · {ago}",
  "Refresh…": "刷新…",
  "Shows the plan first — nothing runs until you confirm": "先显示计划 — 你确认之前什么都不会运行",
  "Install an app…": "安装应用…",
  "Install from a .deb file…": "从 .deb 文件安装…",
