  "Let an agent help…": "让 agent 帮忙…",
  "Starts a temporary helper conversation that knows how to install apps — it can only propose; you approve": "启动一个懂得如何安装应用的临时助手对话 — 它只能提议，由你批准",
  "Could not read the apps on {machine}: {why}": "无法读取{machine}上的应用：{why}",
  "Putting your apps back after this machine was rebuilt…": "这台机器重建了，正在恢复你的应用…",
  "The apps list on this machine could not be read: {why}": "无法读取这台机器上的应用列表：{why}",
  "{name} wants to install {app}": "{name} 想安装 {app}",
  "Declined — the agent is told on its next turn": "已拒绝 — agent 会在下一轮得知",
  "Installed outside VibeSpace — lost when this machine is rebuilt: {pkgs}": "在 VibeSpace 之外安装的 — 机器重建后会丢失：{pkgs}",
  "Keeps them: VibeSpace saves their packages so they come back after a rebuild": "保留它们：VibeSpace 会保存这些包，重建后它们会回来",
  "Nothing installed through VibeSpace yet. An app you install here comes back after this machine is rebuilt.": "还没有通过 VibeSpace 安装任何东西。在这里安装的应用，机器重建后会自动回来。",
  "from a .deb file": "来自 .deb 文件",
  "proposed by {name}": "由 {name} 提议",
  "Package source {app}": "软件源 {app}",
  "Install an app on {machine}": "在{machine}上安装应用",
  "Search the package sources of {machine}. Nothing is installed until you read its plan and press Install.": "搜索{machine}的软件源。在你阅读计划并按下“安装”之前，什么都不会安装。",
  "An app or a package name — gimp, inkscape…": "应用或包名 — gimp、inkscape…",
  "{n} found — pick one to see its plan": "找到 {n} 个 — 选一个查看它的计划",
  "Plan this exact package name": "按这个确切的包名生成计划",
  "The .deb file’s full path on {machine} — in Files, right-click a .deb file and choose “Install this package…”, or type its path. Its plan shows what it installs and whether it runs its own install scripts.": "填写 .deb 文件在{machine}上的完整路径 — 也可以在“文件”里右键 .deb 文件，选择“安装这个包…”。计划会显示它安装什么，以及是否会运行自带的安装脚本。",
  "Show the plan": "显示计划",
  "Type the full path of a .deb file (it starts with / and ends with .deb)": "请输入 .deb 文件的完整路径（以 / 开头，以 .deb 结尾）",
  "A publisher’s own apt repository (for example a browser or an editor vendor). Its key is fetched and its fingerprint shown before anything is added.": "发布者自己的 apt 仓库（例如浏览器或编辑器厂商）。添加任何东西之前，会先获取它的密钥并显示指纹。",
  "Address (https)": "地址（https）",
  "Suite": "发行版",
  "Components": "组件",
  "Signing key address (https)": "签名密钥地址（https）",
  "Fill in the name, the address, the suite and the key address": "请填写名称、地址、发行版和密钥地址",
  "Let an agent help install an app": "让 agent 帮忙安装应用",
  "Starts a temporary helper conversation that knows how to install apps on {machine}. It can only propose an install — you approve it in For you. Close it when it says done.": "启动一个懂得如何在{machine}上安装应用的临时助手对话。它只能提议安装 — 由你在“待你处理”里批准。它说完成后就可以关掉。",
  "What do you want to install? (e.g. an image editor that opens PSD files)": "你想安装什么？（例如一个能打开 PSD 文件的图片编辑器）",
  "What do you want to install?": "你想安装什么？",
  "Start the helper": "启动助手",
  "Could not start the helper: {why}": "无法启动助手：{why}",
  "App install helper": "应用安装助手",
  "Install app · {request}": "装应用 · {request}",
  "The helper started, but it could not be marked as a helper: {why}": "助手已启动，但无法把它标记为助手：{why}",
  "restoring…": "正在恢复…",
  "could not be put back": "无法恢复",
  "not installed here (yet)": "（还）没装在这里",
  "It did not finish on {machine} — the dialog says why": "它没有在{machine}上完成 — 对话框里写了原因",
  "Your installed apps": "你安装的应用",
  "Apps you install here are kept by VibeSpace: they come back by themselves after this machine is rebuilt. An agent can only propose one — you approve it.": "在这里安装的应用由 VibeSpace 保管：机器重建后会自动回来。agent 只能提议安装 — 由你批准。",
  "Install this package…": "安装这个包…",
