  "The files are no longer kept — the card keeps their names, sizes and checksums.": "这些文件已不再保留——卡片保留它们的名称、大小和校验值。",
  "Exactly these bytes are sent; if a file changes, the send is refused.": "发送的正是这些字节；如果文件有变动，发送会被拒绝。",
  // lane chrome-builds-download (design 004): Download another build…
  "Download another build…": "下载其他版本…",
  "Becomes the browser CLI's default build (now {from}): {who} and every conversation's browser start with it next time — after that they can't go back to an older Chrome": "会成为浏览器 CLI 的默认版本（现在是 {from}）：{who} 以及每个对话的浏览器下次启动都会用它——之后就不能再回到更旧的 Chrome",
  "Becomes the browser CLI's default build (now {from}): every conversation's browser starts with it next time — after that it can't go back to an older Chrome": "会成为浏览器 CLI 的默认版本（现在是 {from}）：每个对话的浏览器下次启动都会用它——之后就不能再回到更旧的 Chrome",
  "It also becomes the browser CLI's default build: profiles on the default and every conversation's browser start with it next time.": "它还会成为浏览器 CLI 的默认版本：使用默认版本的配置文件和每个对话的浏览器下次启动都会用它。",
  "From Google's Chrome for Testing — every version, its compatibility said before it downloads.": "来自 Google 的 Chrome for Testing——每个版本在下载前都会说明兼容性。",
  "Downloads are offered on Linux x64 computers; to add a Chrome build on this one ({machine}), run {command} in a terminal.": "下载只在 Linux x64 电脑上提供；要在这台电脑（{machine}）上添加 Chrome 版本，请在终端里运行 {command}。",
  "Downloads to a paired machine aren't offered yet; to add a Chrome build there, run {command} on that machine.": "暂不提供下载到已配对的机器；要在那里添加 Chrome 版本，请在那台机器上运行 {command}。",
  "Chrome for Testing builds, from Google. Once a profile is opened by a Chrome version, every older major is refused for it. Canary and Dev change weekly; Stable is what the browser CLI's own install picks.": "来自 Google 的 Chrome for Testing 版本。一个配置文件一旦被某个 Chrome 版本打开过，所有更低的主版本都不能再用于它。Canary 和 Dev 每周更新；Stable 是浏览器 CLI 自己安装时选的版本。",
  "Chrome {major} · newest {version} · {n} versions": "Chrome {major} · 最新 {version} · 共 {n} 个版本",
  "Downloads are offered on Linux x64 computers; on {machine} install by hand: {command}": "下载只在 Linux x64 电脑上提供；在 {machine} 上请手动安装：{command}",
  "Downloads are offered on Linux x64 computers.": "下载只在 Linux x64 电脑上提供。",
  "Needs about {need} MB free, {free} MB left on {path}": "需要约 {need} MB 可用空间，{path} 上只剩 {free} MB",
  "Already on this computer": "这台电脑上已有",
  "Driven by agent-browser {version}": "由 agent-browser {version} 驱动",
  "Fully classified for the live view": "实时画面已完整分类它的所有方法",
  "Newer than the census ({census}): what it adds is refused by name while you drive the browser; everything else works": "比普查版本（{census}）更新：你亲自操作浏览器时，它新增的方法会被点名拒绝；其他一切照常",
  "Older than the census: a few methods it lacks are listed harmlessly": "比普查版本更旧：它缺少的少数方法只是被无害地列出",
  "Older than the Chrome that last opened {label} ({wrote}) — can't be picked for it; fine for a new profile": "比上次打开“{label}”的 Chrome（{wrote}）更旧——不能用于它；用于新配置文件没问题",
  "A profile opened with it can still switch to CloakBrowser (Free or Pro) later": "用它打开过的配置文件以后仍可切换到 CloakBrowser（免费版或 Pro）",
  "A profile opened with it can switch to CloakBrowser Pro (Chromium {pro}) later, not to Free ({free}): switching down is refused": "用它打开过的配置文件以后可以切换到 CloakBrowser Pro（Chromium {pro}），但不能切换到免费版（{free}）：降级会被拒绝",
  "A profile opened with it can't switch to CloakBrowser later (Free {free} / Pro {pro}): switching down is refused": "用它打开过的配置文件以后不能切换到 CloakBrowser（免费版 {free} / Pro {pro}）：降级会被拒绝",
  "Download Chrome {version}?": "下载 Chrome {version}？",
  "About {size} MB comes from {host} and unpacks to about {unpacked} MB in {root}.": "约 {size} MB，来自 {host}，在 {root} 中解压后约 {unpacked} MB。",
  "It comes from {host} and unpacks into {root}.": "它来自 {host}，解压到 {root}。",
  "It is checked against the server's own length and checksum — Google publishes no separate one. Nothing restarts; it becomes a build you can pick. Chrome for Testing never auto-updates.": "下载后会按服务器自己给出的长度和校验和核对——Google 不另外公布校验和。不会重启任何东西；它会成为一个你可以选择的版本。Chrome for Testing 从不自动更新。",
  "Another install is running — download again when it is done.": "另一个安装正在进行——等它完成后再下载。",
  "That build is already on this computer.": "这个版本已经在这台电脑上了。",
  "unzip is missing on this computer — install it (apt install unzip), then try again.": "这台电脑上没有 unzip——请先安装（apt install unzip）再试。",
  "Google's list pointed that download at another site — VibeSpace refused it.": "Google 的列表把这个下载指向了别的网站——VibeSpace 拒绝了它。",
  "That version is not in Google's list.": "Google 的列表里没有这个版本。",
  "Google's server could not be reached.": "无法连接 Google 的服务器。",
  "Google's list could not be read.": "无法读取 Google 的列表。",
  "Not enough free disk space.": "磁盘可用空间不足。",
  "The downloaded file didn't match the server's length or checksum — nothing was kept.": "下载的文件与服务器给出的长度或校验和不符——什么都没有保留。",
  "The downloaded file isn't a Chrome build VibeSpace can unpack safely — nothing was kept.": "下载的文件不是 VibeSpace 能安全解压的 Chrome 版本——什么都没有保留。",
  "The build could not be unpacked — nothing was kept.": "这个版本无法解压——什么都没有保留。",
  "The downloaded Chrome didn't say the version it should — nothing was kept.": "下载的 Chrome 报出的版本不对——什么都没有保留。",
