  "This channel offers no “send directly”: every message an agent drafts here waits for your approval on the Outbox card.": "这个渠道不提供「直接发送」：agent 在这里起草的每条消息都要等你在发件箱卡片上批准。",
  "Stored on this server. Messages an agent reads are sent to that agent’s model provider (Anthropic for Claude, OpenAI for Codex) to answer, not for training. Removing the account deletes this copy.": "保存在这台服务器上。agent 读到的消息会发给该 agent 的模型厂商（Claude 是 Anthropic，Codex 是 OpenAI）用于回答，不用于训练。移除账号会删除这份副本。",
  "Free plan: {vendor} hides messages older than 90 days.": "免费版：{vendor} 会隐藏 90 天前的消息。",
  "{vendor} serves this app only 15 messages a minute (the limit for an app shared outside its workspace) — make your own app from the Connect link in this workspace.": "{vendor} 只给这个 app 每分钟 15 条消息（这是对分发到工作区外的 app 的限制）——请用连接链接在这个工作区里建你自己的 app。",
  "this channel is archived": "这个频道已归档",
  "this channel is frozen": "这个频道已冻结",
  "only some people may post in this channel": "这个频道只有部分人可以发言",
  "in this channel you may only reply in threads": "在这个频道里只能在话题中回复",
  "your organization has not granted this app access to this conversation": "你的组织没有授权这个 app 访问此会话",
  "the app is installed for the whole organization but not granted to this workspace — Re-authorize from a workspace the app is added to": "应用装在整个组织上，但没有授权给这个工作区——请从已添加该应用的工作区重新授权",
  "your workspace's settings do not allow this": "你所在工作区的设置不允许这样做",
  "your organization's key management hides this content": "你所在组织的密钥管理隐藏了这条内容",
  "the app was installed without a permission this needs — add it on the app's page and paste the new token (Re-authorize)": "安装 app 时没有授予这项所需权限——请在 app 页面添加后粘贴新的 token（重新授权）",
  "the token was revoked or the app was removed — paste a new token (Re-authorize)": "token 已被撤销或 app 已被移除——请粘贴新的 token（重新授权）",
  "this channel does not allow threads": "这个频道不允许话题",
  // design 014 D1 (lane desktop-vnc-native): a Windows / macOS machine's whole desktop
  "its desktop": "它的桌面",
  "its desktop — set up once": "它的桌面 — 需设置一次",
  "{machine} is offline": "{machine}离线",
  "Ready": "就绪",
