  "Ready — it asks for a user name and password": "就绪 — 会要求输入用户名和密码",
  "Ready — it asks for the VNC password": "就绪 — 会要求输入 VNC 密码",
  "Screen Sharing answers, but only with a sign-in this viewer cannot speak — on the Mac, open Screen Sharing’s settings and turn on “VNC viewers may control screen with password”": "屏幕共享有应答，但只提供本查看器不支持的登录方式 — 请在 Mac 上打开屏幕共享的设置，开启「VNC 显示程序可以使用密码控制屏幕」",
  "Set up once on the Mac: System Settings → General → Sharing → turn on Screen Sharing": "在 Mac 上设置一次：系统设置 → 通用 → 共享 → 打开「屏幕共享」",
  "Set up once: install TightVNC Server on {machine} — it listens on that machine only": "设置一次：在{machine}上安装 TightVNC Server — 它只在那台机器本机监听",
  "Only people can see or use a machine’s whole desktop": "只有人能查看或使用一台机器的整个桌面",
  "That command is too long (at most 1000 characters)": "命令太长（最多 1000 个字符）",
  "One line only — a line break would start a second command": "只能一行 — 换行会启动第二条命令",
  "The command holds an invisible character — retype it so what runs is what you see": "命令里有看不见的字符 — 请重新输入，让运行的正是你看到的",
  "The command did not start on {machine}": "命令没能在{machine}上启动",
  "Sign in to {machine}": "登录{machine}",
  "{machine} asks for your Mac user name and password. VibeSpace does not keep them.": "{machine}需要你的 Mac 用户名和密码。VibeSpace 不会保存。",
  "{machine} asks for a user name and password. VibeSpace does not keep them.": "{machine}需要用户名和密码。VibeSpace 不会保存。",
  "{machine} asks for its VNC password. VibeSpace does not keep it.": "{machine}需要它的 VNC 密码。VibeSpace 不会保存。",
  "User name": "用户名",
  "Sign in": "登录",
  "{machine} — its desktop": "{machine} — 它的桌面",
  "This window shows everything on {machine}’s screen, and what you type here goes to it.": "这个窗口显示{machine}屏幕上的一切，你在这里输入的内容会发到那台机器。",
