  "Could not tell this machine’s Windows edition; RemoteApp needs Windows Pro or Enterprise": "看不出这台机器的 Windows 版本；RemoteApp 需要 Windows 专业版或企业版", // lane remoteapp-r1b
  "Remote Desktop": "远程桌面", // lane remoteapp-r1b
