  "The password is sealed on this VibeSpace server; only the Remote Desktop client receives it, when you open an app.": "密码密封保存在这台 VibeSpace 服务器上；只有在你打开应用时，远程桌面客户端才会收到它。", // lane remoteapp-r1b
