  "Its desktop shows everything on {machine}’s screen, and what you type there goes to it. Only people can open it — agents cannot.": "「它的桌面」显示{machine}屏幕上的一切，你在里面输入的内容会发到那台机器。只有人能打开，智能体不能。",
