  "wrong name or password": "用户名或密码不对",
  "the machine went offline": "那台机器离线了",
  "Install TightVNC Server on {machine}": "在{machine}上安装 TightVNC Server",
  "Install asks Windows on {machine} for administrator rights: someone at that machine clicks Yes, then types the VNC password into the window that opens there (VibeSpace never sees it). It runs these commands:": "安装会请{machine}上的 Windows 给出管理员权限：需要有人在那台机器前点「是」，再在弹出的窗口里输入 VNC 密码（VibeSpace 看不到它）。它运行这些命令：",
  "Windows on that machine granted no administrator rights — nobody clicked Yes there. Click Install again with someone at that machine, or paste the commands above into an administrator PowerShell there.": "那台机器上的 Windows 没有给出管理员权限 — 没有人在那里点「是」。请在有人在那台机器前时再点安装，或把上面的命令粘贴到那台机器的管理员 PowerShell 里运行。",
  "The install failed — the administrator window on that machine said why.": "安装失败 — 那台机器上的管理员窗口里写了原因。",
  "The install finished, but nothing answers as a VNC server on port 5900 yet — check again.": "安装完成了，但端口 5900 上还没有 VNC 服务器应答 — 请再检查一次。",
  "TightVNC is for Windows machines — a Mac turns on Screen Sharing instead.": "TightVNC 用于 Windows 机器 — Mac 改为打开「屏幕共享」。",
  "Largest file an agent may pull or push, in MB": "智能体可拉取或推送的最大文件（MB）",
  "Agents with \"Run commands on it\" on a paired machine can copy one file at a time between that machine and this one (vibespace-exit pull / push — sha256-checked, shown as a card and in the machine's command list). A bigger file is refused and nothing is copied. Default 1024 MB (1 GB).": "在已配对机器上拥有“在它上面运行命令”权限的智能体，可以在那台机器与本机之间一次复制一个文件（vibespace-exit pull / push——两端校验 sha256，以卡片和该机器的命令列表显示）。更大的文件会被拒绝，不复制任何内容。默认 1024 MB（1 GB）。",
  "pushed {size} · {check}": "已推送 {size} · {check}",
  "pulled {size} · {check}": "已拉取 {size} · {check}",
  "sha256 verified": "sha256 已校验",
  "size verified": "大小已校验",
  "from here → on the machine": "从本机 → 到该机器",
  "on the machine → here": "从该机器 → 到本机",
