  "The script carries characters that change the order it reads in or are not drawn at all: {codes}": "脚本含有会改变阅读顺序或根本不显示的字符：{codes}",
  "Show full command": "显示完整命令",
  "Hide full command": "收起完整命令",
  "VibeSpace is starting… ({n} sessions reconnected)": "VibeSpace 正在启动…（已重新连接 {n} 个会话）",
  "Waiting for the server ({what}: {reason}) — trying again in {n} s": "正在等待服务器（{what}：{reason}）— {n} 秒后重试",
  "The server did not answer {what} ({reason}) after {n} tries.": "服务器在 {n} 次尝试后仍未响应 {what}（{reason}）。",
  "no answer within {n} s": "{n} 秒内无响应",
  "still starting, waiting on {steps}": "仍在启动，等待 {steps}",
  "network error": "网络错误",
  "This machine keeps no app system.": "这台机器没有应用系统。",
  "This machine already has an app system.": "这台机器已经有应用系统了。",
  "An app system cannot be created on this machine — its image carries neither a base system nor debootstrap.": "这台机器建不了应用系统——它的镜像既没有基础系统包，也没有 debootstrap。",
  "Delete the previous app system first — it is kept until you do.": "请先删除上一个应用系统——你删除之前它一直保留。",
  "Set up the app system on {machine}": "在{machine}上建立应用系统",
  "Repair the app system on {machine}": "修复{machine}上的应用系统",
  "Move your apps to the new system on {machine}": "把{machine}上的应用迁到新系统",
  "Roll back the app system on {machine}": "回滚{machine}上的应用系统",
  "Delete the previous app system on {machine}": "删除{machine}上的上一个应用系统",
  "Set up": "建立",
  "Migrate": "迁移",
  "The app system on {machine} is ready": "{machine}上的应用系统已就绪",
  "It goes into the app system on this machine’s disk — after a rebuild it is simply there, nothing is reinstalled.": "它装进这台机器磁盘上的应用系统——机器重建之后直接就在，不用重装。",
  "in the app system": "在应用系统里",
  "Keep the apps you install in an app system on this machine’s disk — after a rebuild they are simply there.": "把你装的应用放进这台机器磁盘上的应用系统——机器重建之后它们直接就在。",
  "Set up…": "建立…",
  "Your app system was made for another kind of processor — its apps cannot run here until you migrate it.": "你的应用系统是为另一种处理器建的——迁移之前，它里面的应用在这里运行不了。",
  "Your app system cannot be used right now ({why}).": "你的应用系统暂时用不了（{why}）。",
  "The previous app system is kept.": "上一个应用系统还保留着。",
  "Roll back…": "回滚…",
  "1 app is reinstalled at every rebuild — move it into the app system": "1 个应用每次重建都要重装 — 搬进应用系统",
  "{n} apps are reinstalled at every rebuild — move them into the app system": "{n} 个应用每次重建都要重装 — 搬进应用系统",
  "apps::Move…": "搬进去…",
  "apps::Move": "搬进去",
  "Not in the app system you went back to: {names}": "不在你换回的应用系统里：{names}",
  "Install into the app system…": "装进应用系统…",
  "It stays after a rebuild — nothing is reinstalled": "装进应用系统，重建后还在 — 不用重装",
  "Keep on the base only…": "只记在底座上…",
  "Reinstalled at every rebuild": "只记在底座上，每次重建重装",
  "Move your apps into the app system on {machine}": "把{machine}上的应用搬进应用系统",
  "{app}: not moved — {why}": "{app}：不搬 — {why}",
  "{app}: already in the app system — only its record on the base goes": "{app}：已在应用系统里 — 只撤掉底座上的记录",
  "Each app goes into the app system first; only then is it no longer reinstalled at every rebuild. Its programs stay on the base until the next rebuild.": "每个应用先装进应用系统，成功后才不再每次重建重装。底座上的程序在下次重建前还在。",
  "This moves {app} into the app system — it is no longer reinstalled at every rebuild": "这是把 {app} 搬进应用系统 — 以后重建不再重装",
  "{pkgs} is also installed on the base ({apps})": "{pkgs} 在底座上也装着（{apps}）",
  "{n} apps on the base are not in this update — Move… puts them into the app system: {names}": "底座上的 {n} 个应用不在这次更新里 — 用「搬进去…」把它们装进应用系统：{names}",
  "{apps} moved into the app system on {machine}": "{apps} 已搬进{machine}的应用系统",
  "Not moved: {apps}": "没搬成：{apps}",
  "Nothing was moved": "一个都没搬成",
  "This package brings a background service; nothing starts it — use a kept-up job": "这个包带后台服务，没有东西会启动它 — 用常驻任务",
  "Installed; nothing can be started from outside — its files are only in the app system": "装好了；没有可从外面启动的东西，它的文件只在应用系统里",
  "Download failed: {msg}": "下载失败：{msg}",
  "Downloaded the saved version — unsaved changes are not included": "已下载保存过的版本——未保存的修改不包含在内",
  // B-2198 the raw API pass-through (API access dialog, the proposal card, the chat call rows)
  "API access…": "API 访问…",
