  "Cache kept on a network filesystem: {n} items still uploading — it moves to local disk at the next reconnect once they are done": "缓存仍在网络文件系统上：还有 {n} 项正在上传——上传完后，下次重连时移到本地磁盘",
  "Cache kept where it is: its state could not be read ({code}) — not moved until it reads clean": "缓存保持原位：无法读取它的状态（{code}）——读到干净之前不移动",
  "Cache folder setting refused: {dir} is not a writable folder ({code}) — every cache stays where it is until it is fixed or cleared": "缓存文件夹设置被拒绝：{dir} 不是可写的文件夹（{code}）——修好或清空之前，所有缓存保持原位",
  "Cache on a network filesystem: the home folder is not a persistent disk — set Settings › Storage mount cache folder to a persistent local folder": "缓存在网络文件系统上：主目录不是持久磁盘——请在设置 › 存储挂载缓存文件夹指定持久的本地文件夹",
  "Cache on a network filesystem — it moves to local disk at the next reconnect if nothing is waiting to upload": "缓存在网络文件系统上——若没有待上传的内容，下次重连时移到本地磁盘",
  "Cache on a network filesystem with no local disk to move it to — set Settings › Storage mount cache folder (or VIBESPACE_VFS_CACHE_DIR) to a local folder": "缓存在网络文件系统上，且没有可移入的本地磁盘——请在设置 › 存储挂载缓存文件夹（或 VIBESPACE_VFS_CACHE_DIR）指定本地文件夹",
