  "Slack’s last page says “Done here” and this dialog finishes by itself — even when you approved in another browser. If that page shows a code instead, or does not load, paste the code or its address here:": "Slack 最后一页会显示“这里已完成”，这个对话框随后自己完成——即使你是在另一个浏览器里同意的。如果那一页显示的是一串码，或者打不开，把码或它的地址粘到这里：",
  "The sign-in’s last page says it is done and this dialog finishes by itself — even when you approved in another browser. If that page shows a code instead, or does not load, paste the code or its address here:": "登录的最后一页显示已完成后，此对话框会自动结束 —— 即使你是在另一个浏览器里批准的。如果那一页显示的是一个代码，或打不开，请把代码或它的地址粘贴到这里：",
  "Open a new document beside the chat automatically": "自动在聊天旁打开新文档",
