  "Only from these addresses": "只接受这些地址",
  "Blank = any address. Judged on the connecting address; behind a reverse proxy set webhook.trustProxyHops.": "留空 = 任何地址。按连接地址判断；在反向代理后面请设置 webhook.trustProxyHops。",
