  "the machine already streams {live} pictures — at most {cap} for its {n} displays (one per display + one)": "这台机器已在串流 {live} 个画面——它有 {n} 个显示器，最多 {cap} 个（每个显示器一个，再加一个）", // lane desktop-display-modes
