  "Task groups": "任务组", // design q-046 (lane automation-keys-core)
  "Task group": "任务组", // design q-046 (lane automation-keys-core)
  "A conversation granted the key uses it with its own session — it never sees the key's value.": "被授权的会话用自己的会话身份调用——它永远看不到 key 的值。", // design q-046 (lane automation-keys-core)
  "Nothing to pick: no conversation is running and there is no task group": "没有可选的：没有正在运行的会话，也没有任务组", // design q-046 (lane automation-keys-core)
  "Revoke \"{name}\"?": "撤销「{name}」？", // design q-046 (lane automation-keys-core)
  "Every grant of it stops at once and its value leaves the vault. What it already did stays in the audit.": "它的每项授权立即失效，值也从保险库中删除。它已做过的事仍留在审计记录里。", // design q-046 (lane automation-keys-core)
