  "Last used {when}": "最近使用 {when}", // design q-046 (lane automation-keys-core)
  "Never used": "从未使用", // design q-046 (lane automation-keys-core)
  "Not done — {reason}": "没有完成——{reason}", // design q-046 (lane automation-keys-core)
  "{who} wants to use the automation key \"{key}\" ({verb})": "{who} 想用自动化 key「{key}」（{verb}）", // design q-046 (lane automation-keys-core)
  "Allow once lets this call go ahead. Always grants the key to this conversation (the Vault window lists it; take it back there). Deny refuses it and asks no more for 10 minutes. No answer in 60 s: refused. The key's value is never shown to the conversation.": "「允许一次」只放行这一次调用。「一直」把这把 key 授权给这个会话（保险库窗口里能看到，也在那里收回）。「拒绝」拒掉它，10 分钟内不再问。60 秒没人回答：拒绝。这把 key 的值从不给这个会话看。", // design q-046 (lane automation-keys-core)
  "Always for this conversation": "一直（授权给这个会话）", // design q-046 (lane automation-keys-core)
  "Grants the key to this conversation — the Vault window lists it; take it back there": "把这把 key 授权给这个会话——保险库窗口里能看到，也在那里收回", // design q-046 (lane automation-keys-core)
  "Granted — the key is listed with this conversation in the Vault window": "已授权——保险库窗口里这把 key 下列着这个会话", // design q-046 (lane automation-keys-core)
  "Use an automation key you granted it": "用一把你授权给它的自动化 key", // design q-046 (lane automation-keys-core)
  "List its automation keys or their audit": "列出它的自动化 key 或审计记录", // design q-046 (lane automation-keys-core)
