  "Virtual microphone: «{name}»": "虚拟麦克风：「{name}」",
  "No virtual microphone — your voice plays on its speakers": "没有虚拟麦克风——你的声音会从它的扬声器播放",
  "VB-CABLE is installed, but its devices are turned off in Windows’ sound settings": "VB-CABLE 已安装，但它的设备在 Windows 声音设置里被关掉了",
  "This machine did not say where your voice would go": "这台机器没说你的声音会去哪里",
  "Make it the default microphone": "设为默认麦克风",
  "Change it back": "改回",
  "Remove the virtual microphone…": "移除虚拟麦克风…",
  "Reading the microphone…": "正在读取麦克风…",
  "VB-CABLE asks Windows for a restart to finish — the microphone works now": "VB-CABLE 请求重启 Windows 来完成安装——麦克风现在就能用",
  "Your voice → the microphone of its apps: «{name}»": "你的声音 → 本机应用的麦克风『{name}』",
  "The other computer plays your voice on its speakers": "对方电脑会从扬声器播放你的声音",
  "The microphone reaches a Windows or macOS machine": "麦克风用于 Windows 或 macOS 机器",
  "The other computer has no ffmpeg to play your voice — put it on its PATH or in {dir}": "对方电脑没有 ffmpeg，放不出你的声音——把它放在机器的 PATH 或 {dir}",
  "Sound": "声音",
  "Tap to turn the sound on": "点一下开声音",
  "Play this machine’s sound here — off until you press it; nothing is recorded or stored": "在这里播放对方电脑的声音——按下才开；不录制、不保存",
  "Sound on — press to turn it off; nothing is recorded or stored": "声音已开——再按一下关闭；不录制、不保存",
  "This window came back by itself — tap to turn its sound on (the browser waits for your press)": "这个窗口是自动恢复的——点一下开声音（浏览器要等你按一下）",
  "This stream carries no sound — the agent on that machine is too old (reconnect it to upgrade)": "这个串流不带声音——那台电脑上的 agent 太旧（重新连接即可升级）",
  "This machine cannot send its sound (only a Windows or macOS machine can)": "这台电脑发不出它的声音（只有 Windows 或 macOS 电脑可以）",
  "The sound helper did not build on that machine — see the Machines card": "那台电脑上的声音助手没有编译成功——请看机器卡片",
  "That machine has no ffmpeg with an Opus encoder for its sound": "那台电脑没有带 Opus 编码器的 ffmpeg 来编码声音",
  "The Mac needs “Screen & System Audio Recording” for vibespace-screen — the same switch as the picture": "这台 Mac 需要为 vibespace-screen 打开「屏幕与系统录音」——和画面是同一个开关",
  "The Mac’s screen helper was updated — switch “Screen & System Audio Recording” on for it once more": "这台 Mac 的屏幕助手已更新——请为它再打开一次「屏幕与系统录音」",
  "That stream ended": "这个串流已结束",
  "The browser kept the sound muted — press 「声音」 again": "浏览器仍然静音——请再按一次「声音」",
  "The machine could not start its sound — press again": "对方电脑没能开始传声音——请再按一次",
  "Sound uses the same “Screen & System Audio Recording” permission": "声音用的是同一个“屏幕与系统录音”授权",
  "After the screen helper updates, macOS asks you to switch it on once more": "屏幕助手更新后，macOS 需要你再授权一次",
  "Sound: Windows asks for no permission": "声音：Windows 不需要授权",
  "Open this subagent": "打开这个子 agent",
  "This conversation started no subagent with this id that VibeSpace could read": "本对话里没有 VibeSpace 能读到的、使用这个 id 的子 agent",
  "unknown subagent": "未知子 agent",
  "running for": "已运行",
