  "Last progress": "最后进展",
  "Files it wrote": "它写的文件",
  "This harness shows no subagent details": "这个 harness 不显示子 agent 的细节",
  "Context used last turn: {used} tokens. The model's context window is unknown (it is not in this harness's window table), so no percentage is shown.": "上一轮使用的上下文：{used} tokens。这个模型的上下文窗口未知（不在该 harness的窗口表里），所以不显示百分比。",
  "window unknown": "窗口未知",
  "the model's documented window (this harness's window table)": "模型公开的窗口大小（该 harness的窗口表）",
  ", thinking {n} = {pct}% of the total": "，思考 {n} = 合计的 {pct}%",
  "Token total of this conversation, as the harness counts it: {total} (in {inp}, cached {cached}, out {out}{thinking})": "本对话的 token 合计（按该 harness 自己的计数）：{total}（输入 {inp}，缓存 {cached}，输出 {out}{thinking}）",
  "The last turn took {time}": "上一轮用时 {time}",
  "it spent {total} tokens (in {inp}, cached {cached}, out {out}){calls}": "用了 {total} tokens（输入 {inp}，缓存 {cached}，输出 {out}）{calls}",
  " over {n} model calls": "，共 {n} 次模型调用",
  " over one model call": "，共 1 次模型调用",
