  "cache hit rate": "缓存命中率",
  "token total": "token 合计",
  "model it ran on": "实际运行的模型",
  "turn time": "本轮用时",
  "Not reported by this harness: {facts}": "该 harness不报告：{facts}",
  "not reported": "未报告",
  "Node: unknown": "Node：未知",
  "Runtime too old": "运行时过旧",
  "Node {node} is older than {floor}, the release that fixes the Node.js security advisory of {date} ({cves}).": "Node {node} 低于 {floor}——修复 {date} Node.js 安全公告（{cves}）的版本。",
  "Its agent runs the Node its installer provisioned: run the pairing command again on the machine — the installer replaces it with the fixed release. The agent’s own updates never change its Node.": "它的 agent 运行的是安装器自带的 Node：在那台机器上再运行一次配对命令——安装器会把它换成已修复的版本。agent 自己的更新从不更换 Node。",
  "Its agent runs a Node this machine already had, which the installer never replaces: upgrade it to {floor} or newer on the machine, then run the pairing command again so the agent restarts on it.": "它的 agent 运行的是这台机器原有的 Node，安装器从不替换它：请在那台机器上把它升级到 {floor} 或更新，然后再运行一次配对命令，让 agent 在新版本上重启。",
  "Its agent runs this machine’s own Node: upgrade it to {floor} or newer — the agent runs on it from its next connection.": "它的 agent 运行的是这台机器自己的 Node：请把它升级到 {floor} 或更新——下次连接起 agent 就会用它运行。",
  // lane runtime-floor: the Diagnostics report's Node runtime section
  "Node runtime": "Node 运行时",
  "This server runs Node {node}.": "本服务器运行 Node {node}。",
  "Below {floor}, the release that fixes the Node.js security advisory of {date} — the next update installs it for this instance and restarts on it.": "低于 {floor}——修复 {date} Node.js 安全公告的版本。下次更新会为本实例安装它，并在它上面重启。",
  "At or above {floor}, the release that fixes the Node.js security advisory of {date}.": "不低于 {floor}——修复 {date} Node.js 安全公告的版本。",
  "The floor table names no fixed release for Node {major}.": "版本底线表没有为 Node {major} 列出修复版本。",
  "Switched at start from {base} to this instance’s own runtime.": "启动时已从 {base} 切换到本实例自己的运行时。",
  "This instance’s own runtime: {version} (data/runtime/current).": "本实例自己的运行时：{version}（data/runtime/current）。",
  "The boot check is downloading {version}…": "启动检查正在下载 {version}…",
  "The boot check provisioned {version} — the next restart runs on it.": "启动检查已安装 {version}——下次重启即在它上面运行。",
  "The boot check did not provision {version} ({code}).": "启动检查未能安装 {version}（{code}）。",
  "Long-lived token only, without the profile scope: can’t be probed — refreshes when a session uses it": "仅长期 token（无 profile 权限）：无法主动探测，用到时才刷新",
  "Long-lived token only, and claude {cli} isn’t measured with it: can’t be probed — refreshes when a session uses it": "仅长期 token，且 claude {cli} 未测量：无法主动探测，用到时才刷新",
  "Long-lived token only, not in its folder: can’t be probed — refreshes when a session uses it": "仅长期 token，未写入账号目录：无法主动探测，用到时才刷新",
  "Last probe failed: {why}": "上次探测失败：{why}",
  // lane cli-2-1-308-records: a claude build this release has no record table for (src/lib/cli-registration-words.js)
  "claude {v} is not registered — records may show as new fields until the next release": "claude {v} 尚未登记——在下一个版本之前，记录可能显示为新字段",
  "Record draft taken: {file} — {n} changes against claude {against}": "记录草稿已生成：{file}——相对 claude {against} 有 {n} 处变化",
  "Record draft taken: {file}": "记录草稿已生成：{file}",
  "Draft the record table": "生成记录草稿",
  "Reads the installed claude's strings (it is never run) and writes data/claude-cli-dumps/{v}.json — the dump the next release registers it from": "读取已安装的 claude 的字符串（从不运行它），写入 data/claude-cli-dumps/{v}.json——下一个版本据此登记它",
  "the hub's claude": "这个 hub 的 claude",
  "a conversation's records": "某个对话的记录",
  "No draft yet — Manage agents ▸ claude ▸ Draft the record table, or node scripts/claude-cli-dump.mjs --auto": "尚无草稿——管理 agent ▸ claude ▸ 生成记录草稿，或运行 node scripts/claude-cli-dump.mjs --auto",
  "No draft — run node scripts/claude-cli-dump.mjs --auto on the machine whose claude this is": "尚无草稿——请在运行这个 claude 的机器上运行 node scripts/claude-cli-dump.mjs --auto",
  "seen as {where} · first {when}": "见于：{where} · 首次 {when}",
  "Claude builds without a record table": "没有记录表的 claude 版本",
  "Builds of claude this server saw that this release has no record table for (it knows {newest} and older). Until a release registers one, its conversations count the records it added in one quiet chip of their status bar. The draft is the build's static dump — its strings, never run — for the release that registers it.": "本服务器见过、但本版本没有记录表的 claude 版本（它认识 {newest} 及更早的版本）。在某个版本登记它之前，这些对话会在状态栏用一个安静的小标签数出它新增的记录。草稿是该版本的静态转储——只读它的字符串，从不运行——供登记它的版本使用。",
  "Could not draft the record table: {why}": "无法生成记录草稿：{why}",
