  "Joined {names} — can see and message the {n} session(s) in these {g} groups; groups it did not join only reach the sessions it starts itself": "加入了{names} —— 能看到、发消息给这 {g} 组的 {n} 个会话；没加入的组只碰得到它自己开的",
