  "A Terminal has no agent: channels, browser profiles and the vault need an agent, so they are not listed. In this shell you sign in and open browsers yourself.": "终端模式没有 agent：频道、浏览器档案、保险库这些要 agent 才用得上，这里不列。你在这个 shell 里自己登录、自己开浏览器。",
  "Through Task Group {names} · {authority}": "经任务组{names} · {authority}",
  "Except…": "除了…",
