  "{plugin} · its kernel needs Node {need} or later to unpack — this VibeSpace runs on Node {node}; nothing was downloaded": "{plugin} · 解包内核需要 Node {need} 或更高版本——此 VibeSpace 运行在 Node {node} 上；未下载任何内容",
